function complianceStatusBadge(s: ComplianceStatus) {
  const map: Record<ComplianceStatus, string> = {
    'Compliant': 'border-[#86efac] bg-[#dcfce7] text-[#166534]',
    'Due Soon': 'border-[#fcd34d] bg-[#fef3c7] text-[#92400e]',
    'Overdue': 'border-[#fca5a5] bg-[#fee2e2] text-[#b91c1c]',
    'Action Required': 'border-[#fca5a5] bg-[#fee2e2] text-[#b91c1c]',
    'Under Verification': 'border-[#93c5fd] bg-[#dbeafe] text-[#1e40af]',
  }
  return <span className={`text-[10px] font-semibold px-1.5 py-0.5 border ${map[s]}`}>{s}</span>
}

// ── E24 ──────────────────────────────────────────────────────────────────────

function E24CompliancePage({ onBack, onGoToObligation, onGoToE23, onGoToE11, onOpenRegAssistant }: {
  onBack: () => void
  onGoToObligation: (id: string) => void
  onGoToE23: () => void
  onGoToE11: () => void
  onOpenRegAssistant?: (ctx: RegAssistantContext) => void
}) {
  const [view, setView] = useState<'list' | 'calendar'>('list')
  const [deptFilter, setDeptFilter] = useState('All')
  const [catFilter, setCatFilter] = useState('All')
  const [actionOnly, setActionOnly] = useState(false)

  const filtered = COMPLIANCE_OBLIGATIONS.filter(o => {
    if (deptFilter !== 'All' && o.dept !== deptFilter) return false
    if (catFilter !== 'All' && o.category !== catFilter) return false
    if (actionOnly && !o.actionRequired) return false
    return true
  })

  const actionCount = COMPLIANCE_OBLIGATIONS.filter(o => o.actionRequired).length
  const dueSoon = COMPLIANCE_OBLIGATIONS.filter(o => o.status === 'Due Soon').length
  const overdue = COMPLIANCE_OBLIGATIONS.filter(o => o.status === 'Overdue').length
  const renewals = COMPLIANCE_OBLIGATIONS.filter(o => o.category === 'Renewals').length

  // Calendar: show Oct–Dec 2026 months with obligations plotted
  const calMonths = [
    { label: 'October 2026', year: 2026, month: 9 },
    { label: 'November 2026', year: 2026, month: 10 },
    { label: 'December 2026', year: 2026, month: 11 },
    { label: 'March 2027', year: 2027, month: 2 },
    { label: 'September 2027', year: 2027, month: 8 },
    { label: 'December 2027', year: 2027, month: 11 },
  ]

  function obligationsForMonth(year: number, month: number) {
    return COMPLIANCE_OBLIGATIONS.filter(o => {
      if (o.dueDate === 'Ongoing') return false
      const d = new Date(o.dueDateMs)
      return d.getFullYear() === year && d.getMonth() === month
    })
  }

  return (
    <main id="main-content" className="flex-1 bg-[#f8f9fb]" tabIndex={-1}>
      <div className="bg-white border-b border-[#d1d9e0] px-6 py-4">
        <div className="max-w-[1280px] mx-auto">
          <nav className="text-xs text-[#6b7a8d] mb-2 flex items-center gap-1.5">
            <button onClick={onBack} className="hover:text-[#1a3a5c] hover:underline">Dashboard</button>
            <span>›</span>
            <span className="text-[#1a3a5c] font-medium">Compliance Dashboard</span>
          </nav>
          <div className="flex flex-wrap items-start justify-between gap-3">
            <div>
              <h1 className="text-xl font-bold text-[#1a3a5c]">Compliance Dashboard</h1>
              <p className="text-xs text-[#6b7a8d] mt-0.5">Sahyadri Bio-Pharma Pvt Ltd — Chakan Industrial Area Phase II</p>
            </div>
            {onOpenRegAssistant && (
              <RegAssistantTrigger lang="en" size="sm" onClick={() => onOpenRegAssistant({ entryPoint: 'compliance', initialQuestion: 'What is this compliance obligation?' })} />
            )}
          </div>
        </div>
      </div>

      <div className="max-w-[1280px] mx-auto px-6 py-5 space-y-4">
        {/* Summary tiles */}
        <div className="grid grid-cols-2 sm:grid-cols-5 gap-3">
          {[
            { label: 'Action Required', value: actionCount, color: actionCount > 0 ? 'text-[#b91c1c]' : 'text-[#94a3b8]' },
            { label: 'Due Soon', value: dueSoon, color: dueSoon > 0 ? 'text-[#d97706]' : 'text-[#94a3b8]' },
            { label: 'Overdue', value: overdue, color: overdue > 0 ? 'text-[#b91c1c]' : 'text-[#94a3b8]' },
            { label: 'Renewals', value: renewals, color: 'text-[#1a3a5c]' },
            { label: 'Total Obligations', value: COMPLIANCE_OBLIGATIONS.length, color: 'text-[#1a3a5c]' },
          ].map(s => (
            <div key={s.label} className="bg-white border border-[#e2e8f0] px-4 py-3">
              <p className={`text-2xl font-bold ${s.color}`}>{s.value}</p>
              <p className="text-xs text-[#6b7a8d] mt-0.5">{s.label}</p>
            </div>
          ))}
        </div>

        {/* Source notice */}
        <div className="bg-white border border-[#bfdbfe] border-l-4 border-l-[#1d4ed8] px-4 py-3 text-xs text-[#1e3a8a]">
          Compliance obligations below were generated from the conditions attached to your MPCB Consent to Establish approval ({' '}
          <button onClick={onGoToE23} className="underline hover:text-[#1e40af]">CTE-2026-MPCB-41872</button>
          {' '}) and other active approvals. {' '}
          <button onClick={onGoToE11} className="underline hover:text-[#1e40af]">View Document Centre</button>
        </div>

        {/* View toggle + Filters */}
        <div className="bg-white border border-[#e2e8f0] px-4 py-3 flex flex-wrap gap-3 items-center justify-between">
          <div className="flex items-center gap-1 border border-[#d1d9e0]">
            <button onClick={() => setView('list')} className={`text-xs px-3 py-1.5 font-medium border-r border-[#d1d9e0] ${view === 'list' ? 'bg-[#1a3a5c] text-white' : 'text-[#475569] hover:bg-[#f1f5f9]'}`}>List</button>
            <button onClick={() => setView('calendar')} className={`text-xs px-3 py-1.5 font-medium ${view === 'calendar' ? 'bg-[#1a3a5c] text-white' : 'text-[#475569] hover:bg-[#f1f5f9]'}`}>Calendar</button>
          </div>
          <div className="flex flex-wrap items-center gap-3">
            <div className="flex items-center gap-2">
              <label className="text-[10px] font-bold text-[#64748b] uppercase tracking-wider">Department</label>
              <select value={deptFilter} onChange={e => setDeptFilter(e.target.value)} className="text-xs border border-[#d1d9e0] px-2 py-1 focus:outline-none focus:ring-1 focus:ring-[#1a56db]">
                {['All', 'MPCB', 'Fire', 'DISH'].map(v => <option key={v}>{v}</option>)}
              </select>
            </div>
            <div className="flex items-center gap-2">
              <label className="text-[10px] font-bold text-[#64748b] uppercase tracking-wider">Category</label>
              <select value={catFilter} onChange={e => setCatFilter(e.target.value)} className="text-xs border border-[#d1d9e0] px-2 py-1 focus:outline-none focus:ring-1 focus:ring-[#1a56db]">
                {['All', 'Environmental', 'Approval Conditions', 'Renewals', 'Periodic Returns'].map(v => <option key={v}>{v}</option>)}
              </select>
            </div>
            <label className="flex items-center gap-1.5 text-xs text-[#475569] cursor-pointer">
              <input type="checkbox" checked={actionOnly} onChange={e => setActionOnly(e.target.checked)} className="accent-[#1a3a5c]" />
              Action Required only
            </label>
            {(deptFilter !== 'All' || catFilter !== 'All' || actionOnly) && (
              <button onClick={() => { setDeptFilter('All'); setCatFilter('All'); setActionOnly(false) }} className="text-xs text-[#b91c1c] hover:underline">Clear</button>
            )}
          </div>
        </div>

        {view === 'list' ? (
          <div className="bg-white border border-[#e2e8f0] overflow-x-auto">
            <table className="w-full text-xs border-collapse">
              <thead>
                <tr className="bg-[#f8f9fb] border-b border-[#e2e8f0]">
                  {['Obligation', 'Department', 'Category', 'Due Date', 'Frequency', 'Status', 'Action Required'].map(h => (
                    <th key={h} className="text-left px-3 py-2.5 text-[10px] font-semibold text-[#64748b] uppercase tracking-wider border-r border-[#e8edf2] last:border-r-0 whitespace-nowrap">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {filtered.length === 0 ? (
                  <tr><td colSpan={7} className="px-4 py-8 text-center text-[#94a3b8]">No obligations match the current filters.</td></tr>
                ) : filtered.map(o => (
                  <tr key={o.id} onClick={() => onGoToObligation(o.id)} className="border-b border-[#f1f5f9] hover:bg-[#f8f9fb] cursor-pointer">
                    <td className="px-3 py-2.5 border-r border-[#f1f5f9]">
                      <div>
                        <button className="font-medium text-[#1a3a5c] hover:underline text-left leading-snug">{o.name}</button>
                        <p className="text-[10px] font-mono text-[#94a3b8] mt-0.5">{o.id}</p>
                      </div>
                    </td>
                    <td className="px-3 py-2.5 whitespace-nowrap text-[#475569] border-r border-[#f1f5f9]">{o.dept}</td>
                    <td className="px-3 py-2.5 text-[#475569] border-r border-[#f1f5f9]">{o.category}</td>
                    <td className={`px-3 py-2.5 whitespace-nowrap font-medium border-r border-[#f1f5f9] ${o.status === 'Overdue' ? 'text-[#b91c1c]' : o.status === 'Due Soon' ? 'text-[#d97706]' : 'text-[#334155]'}`}>{o.dueDate}</td>
                    <td className="px-3 py-2.5 text-[#475569] border-r border-[#f1f5f9] whitespace-nowrap">{o.frequency}</td>
                    <td className="px-3 py-2.5 whitespace-nowrap border-r border-[#f1f5f9]">{complianceStatusBadge(o.status)}</td>
                    <td className="px-3 py-2.5 min-w-[180px]">
                      {o.actionRequired
                        ? <span className="text-[#b91c1c] leading-snug">{o.actionRequired.split('.')[0]}.</span>
                        : <span className="text-[#94a3b8]">No action required</span>}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          // Calendar view
          <div className="bg-white border border-[#e2e8f0]">
            <div className="px-4 py-2.5 border-b border-[#e8edf2] bg-[#f8f9fb]">
              <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Upcoming Compliance Deadlines</p>
            </div>
            <div className="divide-y divide-[#f1f5f9]">
              {calMonths.map(m => {
                const obs = obligationsForMonth(m.year, m.month)
                if (obs.length === 0) return null
                return (
                  <div key={m.label} className="px-4 py-3">
                    <p className="text-xs font-semibold text-[#1a3a5c] mb-2">{m.label}</p>
                    <div className="space-y-1.5">
                      {obs.map(o => (
                        <div key={o.id} onClick={() => onGoToObligation(o.id)} className="flex items-center gap-3 cursor-pointer hover:bg-[#f8f9fb] px-2 py-1.5 -mx-2">
                          <div className="w-8 text-center shrink-0">
                            <p className="text-lg font-bold text-[#1a3a5c] leading-none">{new Date(o.dueDateMs).getDate()}</p>
                            <p className="text-[8px] text-[#94a3b8] uppercase">{new Date(o.dueDateMs).toLocaleString('en', { month: 'short' })}</p>
                          </div>
                          <div className="flex-1 min-w-0">
                            <p className="text-xs font-medium text-[#1a3a5c] truncate">{o.name}</p>
                            <p className="text-[10px] text-[#94a3b8]">{o.dept} · {o.category}</p>
                          </div>
                          <div className="shrink-0">{complianceStatusBadge(o.status)}</div>
                        </div>
                      ))}
                    </div>
                  </div>
                )
              })}
              {/* Ongoing obligations */}
              <div className="px-4 py-3">
                <p className="text-xs font-semibold text-[#1a3a5c] mb-2">Ongoing</p>
                {COMPLIANCE_OBLIGATIONS.filter(o => o.dueDate === 'Ongoing').map(o => (
                  <div key={o.id} onClick={() => onGoToObligation(o.id)} className="flex items-center gap-3 cursor-pointer hover:bg-[#f8f9fb] px-2 py-1.5 -mx-2">
                    <div className="w-8 text-center shrink-0">
                      <p className="text-[10px] text-[#94a3b8] font-semibold">—</p>
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-xs font-medium text-[#1a3a5c] truncate">{o.name}</p>
                      <p className="text-[10px] text-[#94a3b8]">{o.dept} · {o.frequency}</p>
                    </div>
                    <div className="shrink-0">{complianceStatusBadge(o.status)}</div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>
    </main>
  )
}

// ── E25 ──────────────────────────────────────────────────────────────────────

function E25ComplianceDetailPage({ obligationId, onBack, onGoToE24, onGoToE23, onGoToE11, onGoToDocDetail, onOpenRegAssistant }: {
  obligationId: string
  onBack: () => void
  onGoToE24: () => void
  onGoToE23: () => void
  onGoToE11: () => void
  onGoToDocDetail: (id: string) => void
  onOpenRegAssistant?: (ctx: RegAssistantContext) => void
}) {
  const obl = COMPLIANCE_OBLIGATIONS.find(o => o.id === obligationId) || COMPLIANCE_OBLIGATIONS[0]
  const [ragOpen, setRagOpen] = useState(false)
  const [ragInput, setRagInput] = useState('')
  const [ragMessages, setRagMessages] = useState<{ role: 'user' | 'assistant'; text: string }[]>([])

  const SUGGESTED_PROMPTS = [
    'Why is this compliance obligation required?',
    'Which approval created it?',
    'What condition does it relate to?',
    'What documents are required?',
    'When is it due?',
    'What should I submit?',
  ]

  function handleRagSend(text: string) {
    if (!text.trim()) return
    const responses: Record<string, string> = {
      'Why is this compliance obligation required?': obl.whyRequired,
      'Which approval created it?': `This obligation originates from approval ${obl.sourceApprovalId}. The relevant condition is: "${obl.relevantCondition}"`,
      'What condition does it relate to?': `${obl.sourceCondition}: ${obl.relevantCondition}`,
      'What documents are required?': obl.requiredDocs.length ? obl.requiredDocs.map(d => d.name).join(', ') : 'No specific document upload is required for this obligation — maintain internal records per the condition.',
      'When is it due?': `Due: ${obl.dueDate}. Frequency: ${obl.frequency}.${obl.nextDueDate ? ` Next due: ${obl.nextDueDate}.` : ''}`,
      'What should I submit?': obl.actionRequired || 'No submission is currently required. This obligation is compliant.',
    }
    const reply = responses[text] || `For specific guidance on ${obl.name}, refer to the source approval and relevant regulatory rule, or contact the ${obl.dept} department directly.`
    setRagMessages(prev => [...prev, { role: 'user', text }, { role: 'assistant', text: reply }])
    setRagInput('')
  }

  return (
    <main id="main-content" className="flex-1 bg-[#f8f9fb]" tabIndex={-1}>
      <div className="bg-white border-b border-[#d1d9e0] px-6 py-4">
        <div className="max-w-[1100px] mx-auto">
          <nav className="text-xs text-[#6b7a8d] mb-2 flex items-center gap-1.5">
            <button onClick={onBack} className="hover:text-[#1a3a5c] hover:underline">Dashboard</button>
            <span>›</span>
            <button onClick={onGoToE24} className="hover:text-[#1a3a5c] hover:underline">Compliance Dashboard</button>
            <span>›</span>
            <span className="text-[#1a3a5c] font-medium">Compliance Detail</span>
          </nav>
          <div className="flex flex-wrap items-start justify-between gap-3">
            <div>
              <h1 className="text-xl font-bold text-[#1a3a5c]">{obl.name}</h1>
              <p className="text-xs text-[#6b7a8d] mt-0.5">{obl.dept} · {obl.category} · {obl.id}</p>
            </div>
            <div className="flex items-center gap-2">
              {complianceStatusBadge(obl.status)}
              {onOpenRegAssistant && (
                <RegAssistantTrigger lang="en" size="sm" onClick={() => onOpenRegAssistant({ entryPoint: 'compliance', recordId: obl.id, recordName: obl.name, department: obl.dept, initialQuestion: 'What is this compliance obligation?' })} />
              )}
              <button onClick={onGoToE24} className="text-sm border border-[#d1d9e0] text-[#475569] px-3 py-1.5 hover:bg-[#f1f5f9]">Back to Compliance</button>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-[1100px] mx-auto px-6 py-5 grid grid-cols-1 lg:grid-cols-3 gap-5">
        {/* Main column */}
        <div className="lg:col-span-2 space-y-4">
          {/* Action banner */}
          {obl.actionRequired && (
            <div className={`bg-white border-l-4 px-5 py-3 ${obl.status === 'Overdue' ? 'border border-[#fca5a5] border-l-[#b91c1c]' : 'border border-[#fcd34d] border-l-[#d97706]'}`}>
              <p className={`text-sm font-semibold ${obl.status === 'Overdue' ? 'text-[#b91c1c]' : 'text-[#92400e]'}`}>{obl.status}</p>
              <p className={`text-xs mt-0.5 ${obl.status === 'Overdue' ? 'text-[#b91c1c]' : 'text-[#92400e]'}`}>{obl.actionRequired}</p>
            </div>
          )}

          {/* Obligation information */}
          <div className="bg-white border border-[#e2e8f0]">
            <div className="px-4 py-2.5 border-b border-[#e8edf2] bg-[#f8f9fb]">
              <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Obligation Information</p>
            </div>
            <div className="divide-y divide-[#f1f5f9]">
              {[
                { label: 'Obligation ID', value: obl.id },
                { label: 'Obligation', value: obl.name },
                { label: 'Department', value: obl.dept },
                { label: 'Category', value: obl.category },
                { label: 'Due Date', value: obl.dueDate },
                { label: 'Frequency', value: obl.frequency },
                ...(obl.nextDueDate ? [{ label: 'Next Due Date', value: obl.nextDueDate }] : []),
                { label: 'Status', value: null as null, badge: complianceStatusBadge(obl.status) },
                { label: 'Verification', value: obl.verification, badge: null as null },
              ].map(r => (
                <div key={r.label} className="px-4 py-2.5 flex justify-between items-center text-sm gap-3">
                  <span className="text-[#6b7a8d] shrink-0">{r.label}</span>
                  {r.badge ?? <span className="text-[#334155] font-medium text-right">{r.value}</span>}
                </div>
              ))}
            </div>
          </div>

          {/* Description */}
          <div className="bg-white border border-[#e2e8f0]">
            <div className="px-4 py-2.5 border-b border-[#e8edf2] bg-[#f8f9fb]">
              <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">What This Obligation Requires</p>
            </div>
            <div className="px-4 py-3 text-xs text-[#334155] leading-relaxed">{obl.description}</div>
          </div>

          {/* Approval → Condition → Obligation traceability */}
          <div className="bg-white border border-[#e2e8f0]">
            <div className="px-4 py-2.5 border-b border-[#e8edf2] bg-[#f8f9fb]">
              <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Source — Approval / Condition</p>
            </div>
            <div className="px-4 py-4 space-y-2 text-xs">
              <div className="flex items-start gap-3">
                <div className="text-[10px] font-bold text-[#94a3b8] uppercase tracking-wider shrink-0 w-24 pt-0.5">Approval</div>
                <div>
                  <button onClick={onGoToE23} className="font-medium text-[#1a56db] hover:underline">{obl.sourceApprovalId}</button>
                  <p className="text-[#6b7a8d] mt-0.5">MPCB Consent to Establish — Approved 10 Oct 2026</p>
                </div>
              </div>
              <div className="ml-6 border-l-2 border-[#e2e8f0] pl-4 space-y-2">
                <div className="flex items-start gap-3">
                  <div className="text-[10px] font-bold text-[#94a3b8] uppercase tracking-wider shrink-0 w-20 pt-0.5">Condition</div>
                  <div>
                    <p className="font-medium text-[#334155]">{obl.sourceCondition}</p>
                    <p className="text-[#475569] leading-relaxed mt-0.5">"{obl.relevantCondition}"</p>
                  </div>
                </div>
                <div className="flex items-start gap-3">
                  <div className="text-[10px] font-bold text-[#94a3b8] uppercase tracking-wider shrink-0 w-20 pt-0.5">Obligation</div>
                  <p className="text-[#334155] font-medium">{obl.name}</p>
                </div>
              </div>
              <div className="pt-1">
                <p className="text-[10px] font-semibold text-[#94a3b8] uppercase tracking-wider mb-1">Why Required</p>
                <p className="text-[#475569] leading-relaxed">{obl.whyRequired}</p>
              </div>
              <button onClick={onGoToE23} className="text-xs text-[#1a56db] hover:underline block pt-1">View Source Approval (E23) →</button>
            </div>
          </div>

          {/* Required documents */}
          {obl.requiredDocs.length > 0 && (
            <div className="bg-white border border-[#e2e8f0]">
              <div className="px-4 py-2.5 border-b border-[#e8edf2] bg-[#f8f9fb]">
                <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Required Documents</p>
              </div>
              <div className="divide-y divide-[#f1f5f9]">
                {obl.requiredDocs.map(d => (
                  <div key={d.id} className="px-4 py-2.5 flex items-center justify-between text-sm">
                    <p className="text-[#334155] font-medium">{d.name}</p>
                    <button onClick={() => onGoToDocDetail(d.id)} className="text-xs text-[#1a56db] hover:underline shrink-0 ml-3">View in E12</button>
                  </div>
                ))}
              </div>
              <div className="px-4 py-2.5 border-t border-[#e8edf2]">
                <button onClick={onGoToE11} className="text-xs text-[#1a56db] hover:underline">Document Centre (E11) →</button>
              </div>
            </div>
          )}

          {/* Previous submission */}
          <div className="bg-white border border-[#e2e8f0]">
            <div className="px-4 py-2.5 border-b border-[#e8edf2] bg-[#f8f9fb]">
              <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Previous Submission</p>
            </div>
            {obl.previousSubmission ? (
              <div className="divide-y divide-[#f1f5f9]">
                {[
                  { label: 'Submission Date', value: obl.previousSubmission.date },
                  { label: 'Reference', value: obl.previousSubmission.ref },
                  { label: 'State', value: obl.previousSubmission.state },
                ].map(r => (
                  <div key={r.label} className="px-4 py-2.5 flex justify-between text-sm">
                    <span className="text-[#6b7a8d]">{r.label}</span>
                    <span className="font-medium text-[#334155]">{r.value}</span>
                  </div>
                ))}
              </div>
            ) : (
              <div className="px-4 py-3 text-sm text-[#94a3b8]">No previous submission recorded.</div>
            )}
          </div>

          {/* Regulatory Assistant */}
          <div className="bg-white border border-[#e2e8f0]">
            <div className="px-4 py-2.5 border-b border-[#e8edf2] bg-[#f8f9fb] flex items-center justify-between">
              <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Regulatory Assistant</p>
              <button onClick={() => setRagOpen(o => !o)} className="text-xs text-[#1a56db] hover:underline">{ragOpen ? 'Close' : 'Ask a question'}</button>
            </div>
            {!ragOpen && (
              <div className="px-4 py-3">
                <div className="flex flex-wrap gap-2">
                  {SUGGESTED_PROMPTS.map(p => (
                    <button key={p} onClick={() => { setRagOpen(true); handleRagSend(p) }} className="text-xs border border-[#d1d9e0] text-[#475569] px-2.5 py-1 hover:bg-[#f1f5f9] hover:text-[#1a3a5c] hover:border-[#1a3a5c] transition-colors">{p}</button>
                  ))}
                </div>
              </div>
            )}
            {ragOpen && (
              <div className="px-4 py-3 space-y-3">
                {ragMessages.length > 0 && (
                  <div className="space-y-2 max-h-64 overflow-y-auto">
                    {ragMessages.map((m, i) => (
                      <div key={i} className={`text-xs px-3 py-2 border ${m.role === 'user' ? 'bg-[#f8f9fb] border-[#e2e8f0] text-[#334155]' : 'bg-white border-[#d1d9e0] text-[#1a3a5c] leading-relaxed'}`}>
                        {m.role === 'assistant' && <p className="text-[10px] font-bold text-[#94a3b8] uppercase tracking-wider mb-1">Regulatory Assistant</p>}
                        {m.role === 'user' && <p className="text-[10px] font-bold text-[#94a3b8] uppercase tracking-wider mb-1">Your Question</p>}
                        <p>{m.text}</p>
                      </div>
                    ))}
                  </div>
                )}
                <div className="flex flex-wrap gap-1.5 border-t border-[#f1f5f9] pt-2">
                  {SUGGESTED_PROMPTS.map(p => (
                    <button key={p} onClick={() => handleRagSend(p)} className="text-xs border border-[#d1d9e0] text-[#475569] px-2 py-1 hover:bg-[#f1f5f9]">{p}</button>
                  ))}
                </div>
                <div className="flex gap-2">
                  <input value={ragInput} onChange={e => setRagInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleRagSend(ragInput)} placeholder="Ask about this compliance obligation…" className="flex-1 text-xs border border-[#d1d9e0] px-3 py-1.5 focus:outline-none focus:ring-1 focus:ring-[#1a56db]" />
                  <button onClick={() => handleRagSend(ragInput)} className="text-xs bg-[#1a3a5c] text-white px-3 py-1.5 hover:bg-[#0f2540]">Ask</button>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Sidebar */}
        <div className="space-y-4">
          {/* Actions */}
          <div className="bg-white border border-[#e2e8f0]">
            <div className="px-3 py-2.5 border-b border-[#e8edf2] bg-[#f8f9fb]">
              <p className="text-xs font-bold text-[#1a3a5c]">Actions</p>
            </div>
            <div className="px-3 py-3 flex flex-col gap-2">
              {obl.actionRequired && (
                <button className="text-sm bg-[#1a3a5c] text-white border border-[#1a3a5c] px-3 py-1.5 hover:bg-[#0f2540] text-left font-semibold">
                  {obl.category === 'Renewals' ? 'Start Renewal Application' : 'Submit Return / Evidence'}
                </button>
              )}
              <button onClick={onGoToE23} className="text-sm border border-[#d1d9e0] text-[#1a3a5c] px-3 py-1.5 hover:bg-[#f1f5f9] text-left">View Source Approval (E23)</button>
              {obl.requiredDocs.length > 0 && <button onClick={onGoToE11} className="text-sm border border-[#d1d9e0] text-[#1a3a5c] px-3 py-1.5 hover:bg-[#f1f5f9] text-left">View Document Centre (E11)</button>}
              <button onClick={() => setRagOpen(true)} className="text-sm border border-[#d1d9e0] text-[#1a3a5c] px-3 py-1.5 hover:bg-[#f1f5f9] text-left">Ask Regulatory Assistant</button>
            </div>
          </div>

          {/* Status summary */}
          <div className="bg-white border border-[#e2e8f0]">
            <div className="px-3 py-2.5 border-b border-[#e8edf2]">
              <p className="text-xs font-bold text-[#1a3a5c]">Current State</p>
            </div>
            <div className="px-3 py-3 space-y-2 text-xs">
              <div className="flex items-center justify-between">
                <span className="text-[#6b7a8d]">Compliance Status</span>
                {complianceStatusBadge(obl.status)}
              </div>
              <div className="flex items-center justify-between">
                <span className="text-[#6b7a8d]">Verification</span>
                <span className="font-medium text-[#334155]">{obl.verification}</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-[#6b7a8d]">Due</span>
                <span className={`font-medium ${obl.status === 'Overdue' ? 'text-[#b91c1c]' : obl.status === 'Due Soon' ? 'text-[#d97706]' : 'text-[#334155]'}`}>{obl.dueDate}</span>
              </div>
            </div>
          </div>

          {/* Navigate */}
          <div className="bg-white border border-[#e2e8f0]">
            <div className="px-3 py-2.5 border-b border-[#e8edf2]">
              <p className="text-xs font-bold text-[#1a3a5c]">Navigate</p>
            </div>
            <div className="px-3 py-3 flex flex-col gap-1.5 text-xs">
              <button onClick={onGoToE24} className="text-left text-[#1a56db] hover:underline">Compliance Dashboard (E24)</button>
              <button onClick={onGoToE23} className="text-left text-[#1a56db] hover:underline">Source Approval (E23)</button>
              <button onClick={onGoToE11} className="text-left text-[#1a56db] hover:underline">Document Centre (E11)</button>
            </div>
          </div>
        </div>
      </div>
    </main>
  )
}

// ─── E23 — Approval / Decision Detail ─────────────────────────────────────────

type DecisionState = 'approved' | 'rejected' | 'correction'

interface DecisionRecord {
  decisionId: string
  appId: string
  dept: string
  service: string
  state: DecisionState
  decisionDate: string
  // Approved
  approvalId?: string
  certId?: string
  certDocId?: string
  issueDate?: string
  expiryDate?: string
  conditions?: string[]
  specialConditions?: string[]
  complianceGenerated?: boolean
  downstreamUnlocked?: { label: string; status: string }[]
  // Rejected
  rejectionReason?: string
  officerRemarks?: string
  downstreamBlocked?: string[]
  // Correction
  queryId?: string
  correctionNote?: string
  // Shared
  inspectionId?: string
  versionHistory?: { version: string; date: string; note: string }[]
}

const SAMPLE_DECISION: DecisionRecord = {
  decisionId: 'DEC-2026-MPCB-00412',
  appId: 'APP-2026-MPCB-00412',
  dept: 'MPCB',
  service: 'Consent to Establish',
  state: 'approved',
  decisionDate: '10 Oct 2026',
  approvalId: 'CTE-2026-MPCB-41872',
  certId: 'CERT-CTE-2026-41872',
  certDocId: 'DOC-003',
  issueDate: '10 Oct 2026',
  expiryDate: '09 Oct 2031',
  conditions: [
    'ETP must be maintained at minimum 70 KL/day design capacity at all times.',
    'Effluent quality must comply with MPCB Schedule VI parameters before discharge to CETP.',
    'Stack emissions must not exceed prescribed limits. Monthly stack monitoring required.',
    'Hazardous waste disposal exclusively through MPCB-authorised transporters and disposal sites.',
    'Annual environmental audit report to be submitted to MPCB by 31 March each year.',
    'Any process change, capacity increase, or product addition must be intimated to MPCB in advance.',
  ],
  specialConditions: [
    'ETP commissioning report must be submitted to MPCB within 30 days of trial production.',
    'All wastewater manifest records must be maintained for a minimum of 5 years and produced on demand.',
  ],
  complianceGenerated: true,
  downstreamUnlocked: [
    { label: 'MIDC Building / Planning Approval', status: 'Proceeding — Document Scrutiny' },
    { label: 'Provisional Fire NOC', status: 'Proceeding — Inspection Scheduled' },
    { label: 'DISH Factory Registration', status: 'Proceeding — Submitted' },
    { label: 'Boiler Registration', status: 'Now Eligible — Awaiting Submission' },
  ],
  inspectionId: 'INS-002',
  versionHistory: [
    { version: 'Decision v1 — Current', date: '10 Oct 2026', note: 'Original decision issued on Resubmission #2 (APP-2026-MPCB-00412-R2).' },
  ],
}

function decisionStateBanner(state: DecisionState) {
  if (state === 'approved') return (
    <div className="bg-white border border-[#86efac] border-l-4 border-l-[#15803d] px-5 py-3">
      <p className="text-sm font-bold text-[#166534]">Decision: Approved</p>
      <p className="text-xs text-[#166534] mt-0.5">The department has approved this application. Approval certificate and conditions are shown below.</p>
    </div>
  )
  if (state === 'rejected') return (
    <div className="bg-white border border-[#fca5a5] border-l-4 border-l-[#b91c1c] px-5 py-3">
      <p className="text-sm font-bold text-[#b91c1c]">Decision: Rejected</p>
      <p className="text-xs text-[#b91c1c] mt-0.5">The department has rejected this application. Reason and downstream impact are shown below.</p>
    </div>
  )
  return (
    <div className="bg-white border border-[#fcd34d] border-l-4 border-l-[#d97706] px-5 py-3">
      <p className="text-sm font-bold text-[#92400e]">Status: Correction Required</p>
      <p className="text-xs text-[#92400e] mt-0.5">The application remains in the active rework lifecycle. A final decision has not yet been issued.</p>
    </div>
  )
}

function decisionStateBadge(state: DecisionState) {
  if (state === 'approved') return <span className="text-[10px] font-semibold px-1.5 py-0.5 border border-[#86efac] bg-[#dcfce7] text-[#166534]">Approved</span>
  if (state === 'rejected') return <span className="text-[10px] font-semibold px-1.5 py-0.5 border border-[#fca5a5] bg-[#fee2e2] text-[#b91c1c]">Rejected</span>
  return <span className="text-[10px] font-semibold px-1.5 py-0.5 border border-[#fcd34d] bg-[#fef3c7] text-[#92400e]">Correction Required</span>
}

function E23DecisionPage({ onBack, onGoToE19, onGoToE22, onGoToE11, onGoToDocDetail, onGoToE09, onGoToE13, onGoToE10, onGoToE20, onGoToE24 }: {
  onBack: () => void
  onGoToE19: () => void
  onGoToE22: () => void
  onGoToE11: () => void
  onGoToDocDetail: (id: string) => void
  onGoToE09: () => void
  onGoToE13: () => void
  onGoToE10: (id: string) => void
  onGoToE20: () => void
  onGoToE24: () => void
}) {
  const dec = SAMPLE_DECISION

  return (
    <main id="main-content" className="flex-1 bg-[#f8f9fb]" tabIndex={-1}>
      <div className="bg-white border-b border-[#d1d9e0] px-6 py-4">
        <div className="max-w-[1100px] mx-auto">
          <nav className="text-xs text-[#6b7a8d] mb-2 flex items-center gap-1.5">
            <button onClick={onBack} className="hover:text-[#1a3a5c] hover:underline">Dashboard</button>
            <span>›</span>
            <button onClick={onGoToE19} className="hover:text-[#1a3a5c] hover:underline">Applications</button>
            <span>›</span>
            <span className="text-[#1a3a5c] font-medium">Approval / Decision</span>
          </nav>
          <div className="flex flex-wrap items-start justify-between gap-3">
            <div>
              <h1 className="text-xl font-bold text-[#1a3a5c]">Approval / Decision Detail</h1>
              <p className="text-xs text-[#6b7a8d] mt-0.5">{dec.dept} — {dec.service}</p>
              <p className="text-xs text-[#6b7a8d]">Sahyadri Bio-Pharma Pvt Ltd · Chakan Industrial Area Phase II</p>
            </div>
            <div>{decisionStateBadge(dec.state)}</div>
          </div>
        </div>
      </div>

      <div className="max-w-[1100px] mx-auto px-6 py-5 grid grid-cols-1 lg:grid-cols-3 gap-5">
        {/* Main column */}
        <div className="lg:col-span-2 space-y-4">
          {/* Decision banner */}
          {decisionStateBanner(dec.state)}

          {/* Decision / Application Information */}
          <div className="bg-white border border-[#e2e8f0]">
            <div className="px-4 py-2.5 border-b border-[#e8edf2] bg-[#f8f9fb]">
              <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Decision Information</p>
            </div>
            <div className="divide-y divide-[#f1f5f9]">
              {[
                { label: 'Decision ID', value: dec.decisionId },
                { label: 'Application ID', value: dec.appId },
                { label: 'Department', value: dec.dept },
                { label: 'Service', value: dec.service },
                { label: 'Decision Date', value: dec.decisionDate },
                { label: 'Decision', value: null, badge: decisionStateBadge(dec.state) },
                ...(dec.approvalId ? [{ label: 'Approval / Order ID', value: dec.approvalId, badge: null as null }] : []),
                ...(dec.certId ? [{ label: 'Certificate ID', value: dec.certId, badge: null as null }] : []),
                ...(dec.inspectionId ? [{ label: 'Related Inspection', value: dec.inspectionId, badge: null as null }] : []),
              ].map(r => (
                <div key={r.label} className="px-4 py-2.5 flex justify-between items-center text-sm gap-3">
                  <span className="text-[#6b7a8d] shrink-0">{r.label}</span>
                  {r.badge ?? <span className="text-[#334155] font-medium font-mono text-right">{r.value}</span>}
                </div>
              ))}
            </div>
          </div>

          {/* Approved: Approval details */}
          {dec.state === 'approved' && (
            <>
              <div className="bg-white border border-[#e2e8f0]">
                <div className="px-4 py-2.5 border-b border-[#e8edf2] bg-[#f8f9fb]">
                  <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Approval Certificate</p>
                </div>
                <div className="divide-y divide-[#f1f5f9]">
                  {[
                    { label: 'Certificate ID', value: dec.certId! },
                    { label: 'Issue Date', value: dec.issueDate! },
                    { label: 'Expiry Date', value: dec.expiryDate! },
                    { label: 'Validity Period', value: '5 years' },
                    { label: 'Renewal Required', value: 'Yes — before 09 Oct 2031' },
                    { label: 'Document in Centre', value: 'DOC-003 · E11 Document Centre' },
                  ].map(r => (
                    <div key={r.label} className="px-4 py-2.5 flex justify-between text-sm gap-3">
                      <span className="text-[#6b7a8d] shrink-0">{r.label}</span>
                      <span className="text-[#334155] font-medium text-right">{r.value}</span>
                    </div>
                  ))}
                </div>
                <div className="px-4 py-2.5 border-t border-[#e8edf2] flex gap-3">
                  <button onClick={() => onGoToDocDetail(dec.certDocId!)} className="text-xs text-[#1a56db] hover:underline">View Certificate →</button>
                  <button onClick={onGoToE11} className="text-xs text-[#1a56db] hover:underline">View in Document Centre (E11) →</button>
                </div>
              </div>

              {/* Conditions */}
              <div className="bg-white border border-[#e2e8f0]">
                <div className="px-4 py-2.5 border-b border-[#e8edf2] bg-[#f8f9fb]">
                  <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Conditions</p>
                </div>
                <div className="px-4 py-3">
                  <ul className="space-y-2">
                    {dec.conditions!.map((c, i) => (
                      <li key={i} className="text-xs text-[#334155] flex gap-2">
                        <span className="shrink-0 font-mono text-[#94a3b8]">{String(i + 1).padStart(2, '0')}.</span>
                        <span className="leading-relaxed">{c}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>

              {/* Special Conditions */}
              {dec.specialConditions && dec.specialConditions.length > 0 && (
                <div className="bg-white border border-[#fcd34d]">
                  <div className="px-4 py-2.5 border-b border-[#fef3c7] bg-[#fffbeb]">
                    <p className="text-xs font-bold text-[#92400e] uppercase tracking-wider">Special Conditions</p>
                  </div>
                  <div className="px-4 py-3">
                    <ul className="space-y-2">
                      {dec.specialConditions.map((c, i) => (
                        <li key={i} className="text-xs text-[#334155] flex gap-2">
                          <span className="shrink-0 font-mono text-[#d97706]">SC{i + 1}.</span>
                          <span className="leading-relaxed">{c}</span>
                        </li>
                      ))}
                    </ul>
                  </div>
                </div>
              )}

              {/* Dependency Effect */}
              <div className="bg-white border border-[#e2e8f0]">
                <div className="px-4 py-2.5 border-b border-[#e8edf2] bg-[#f8f9fb]">
                  <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Dependency Effect</p>
                </div>
                <div className="px-4 py-3 space-y-1.5">
                  <p className="text-xs text-[#6b7a8d] mb-3">The following downstream requirements are now available as a result of this approval.</p>
                  <div className="text-xs font-semibold text-[#166534] mb-2">MPCB CTE — Approved</div>
                  {dec.downstreamUnlocked!.map((d, i) => (
                    <div key={i} className="flex items-start gap-3 pl-4">
                      <span className="shrink-0 text-[#94a3b8] mt-0.5">↓</span>
                      <div>
                        <p className="font-medium text-[#1a3a5c]">{d.label}</p>
                        <p className="text-[#15803d]">{d.status}</p>
                      </div>
                    </div>
                  ))}
                  <div className="flex gap-3 pt-2">
                    <button onClick={onGoToE09} className="text-xs text-[#1a56db] hover:underline">View Regulatory Journey (E09) →</button>
                    <button onClick={onGoToE13} className="text-xs text-[#1a56db] hover:underline">View Dependency Graph (E13) →</button>
                  </div>
                </div>
              </div>

              {/* Compliance */}
              {dec.complianceGenerated && (
                <div className="bg-white border border-[#e2e8f0]">
                  <div className="px-4 py-2.5 border-b border-[#e8edf2] bg-[#f8f9fb]">
                    <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Compliance Obligations</p>
                  </div>
                  <div className="px-4 py-3 text-xs text-[#475569] space-y-1.5">
                    <p>This approval generates the following ongoing compliance obligations:</p>
                    <ul className="space-y-1 mt-2">
                      {[
                        'Annual environmental audit report — submit by 31 March each year',
                        'Monthly stack monitoring — results to be uploaded quarterly',
                        'ETP commissioning report — within 30 days of trial production',
                        'Hazardous waste manifest records — maintain for 5 years',
                      ].map((ob, i) => (
                        <li key={i} className="flex gap-2">
                          <span className="shrink-0 text-[#d1d9e0]">—</span>
                          <span>{ob}</span>
                        </li>
                      ))}
                    </ul>
                    <div className="pt-2 flex gap-3">
                      <button onClick={onGoToE24} className="text-xs text-[#1a56db] hover:underline">View Compliance Dashboard (E24) →</button>
                    </div>
                  </div>
                </div>
              )}
            </>
          )}

          {/* Rejected state */}
          {dec.state === 'rejected' && (
            <>
              <div className="bg-white border border-[#e2e8f0]">
                <div className="px-4 py-2.5 border-b border-[#e8edf2] bg-[#f8f9fb]">
                  <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Rejection Details</p>
                </div>
                <div className="px-4 py-3 space-y-3 text-xs">
                  <div>
                    <p className="text-[10px] font-semibold text-[#94a3b8] uppercase tracking-wider mb-1">Rejection Reason</p>
                    <p className="text-[#334155] leading-relaxed">{dec.rejectionReason}</p>
                  </div>
                  {dec.officerRemarks && (
                    <div>
                      <p className="text-[10px] font-semibold text-[#94a3b8] uppercase tracking-wider mb-1">Officer Remarks</p>
                      <p className="text-[#334155] leading-relaxed">{dec.officerRemarks}</p>
                    </div>
                  )}
                </div>
              </div>
              {dec.downstreamBlocked && dec.downstreamBlocked.length > 0 && (
                <div className="bg-white border border-[#e2e8f0]">
                  <div className="px-4 py-2.5 border-b border-[#e8edf2] bg-[#f8f9fb]">
                    <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Downstream Impact</p>
                  </div>
                  <div className="px-4 py-3 space-y-1.5 text-xs">
                    {dec.downstreamBlocked.map((d, i) => (
                      <div key={i} className="flex items-center gap-2">
                        <span className="text-[#b91c1c] shrink-0">—</span>
                        <span className="text-[#334155]">{d}</span>
                        <span className="text-[10px] font-semibold border border-[#fca5a5] bg-[#fee2e2] text-[#b91c1c] px-1.5 py-0.5 ml-auto shrink-0">Blocked</span>
                      </div>
                    ))}
                    <button onClick={onGoToE13} className="text-xs text-[#1a56db] hover:underline block pt-1">View Dependency Graph (E13) →</button>
                  </div>
                </div>
              )}
            </>
          )}

          {/* Correction state */}
          {dec.state === 'correction' && (
            <div className="bg-white border border-[#e2e8f0]">
              <div className="px-4 py-2.5 border-b border-[#e8edf2] bg-[#f8f9fb]">
                <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Correction Details</p>
              </div>
              <div className="px-4 py-3 space-y-3 text-xs">
                <p className="text-[#334155]">{dec.correctionNote}</p>
                <div className="flex gap-2">
                  <button onClick={onGoToE20} className="text-xs border border-[#d1d9e0] text-[#1a3a5c] px-3 py-1.5 hover:bg-[#f1f5f9]">View Query / Correction (E20) →</button>
                </div>
              </div>
            </div>
          )}

          {/* Version History */}
          <div className="bg-white border border-[#e2e8f0]">
            <div className="px-4 py-2.5 border-b border-[#e8edf2] bg-[#f8f9fb]">
              <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Version History</p>
            </div>
            <div className="divide-y divide-[#f1f5f9]">
              {dec.versionHistory!.map((v, i) => (
                <div key={i} className="px-4 py-3 text-xs">
                  <div className="flex items-center gap-2 mb-0.5">
                    <p className="font-semibold text-[#1a3a5c]">{v.version}</p>
                    {i === 0 && <span className="text-[10px] font-semibold border border-[#93c5fd] bg-[#dbeafe] text-[#1e40af] px-1.5 py-0.5">Current</span>}
                  </div>
                  <p className="text-[#94a3b8] text-[10px] mb-1">{v.date}</p>
                  <p className="text-[#475569]">{v.note}</p>
                </div>
              ))}
              <div className="px-4 py-2.5 text-xs text-[#6b7a8d]">
                Application version: Resubmission #2 (APP-2026-MPCB-00412-R2) · Original: APP-2026-MPCB-00412
              </div>
            </div>
          </div>
        </div>

        {/* Sidebar */}
        <div className="space-y-4">
          {/* Actions */}
          <div className="bg-white border border-[#e2e8f0]">
            <div className="px-3 py-2.5 border-b border-[#e8edf2] bg-[#f8f9fb]">
              <p className="text-xs font-bold text-[#1a3a5c]">Actions</p>
            </div>
            <div className="px-3 py-3 flex flex-col gap-2 text-xs">
              {dec.state === 'approved' && (
                <>
                  <button onClick={() => onGoToDocDetail(dec.certDocId!)} className="text-left border border-[#d1d9e0] text-[#1a3a5c] px-3 py-1.5 hover:bg-[#f1f5f9]">View Certificate</button>
                  <button onClick={onGoToE11} className="text-left border border-[#d1d9e0] text-[#1a3a5c] px-3 py-1.5 hover:bg-[#f1f5f9]">View in Document Centre</button>
                  <button onClick={onGoToE24} className="text-left border border-[#d1d9e0] text-[#1a3a5c] px-3 py-1.5 hover:bg-[#f1f5f9]">View Compliance Obligations (E24)</button>
                  <button onClick={onGoToE09} className="text-left border border-[#d1d9e0] text-[#1a3a5c] px-3 py-1.5 hover:bg-[#f1f5f9]">View Regulatory Journey</button>
                </>
              )}
              {dec.state === 'rejected' && (
                <>
                  <button onClick={onGoToE13} className="text-left border border-[#d1d9e0] text-[#1a3a5c] px-3 py-1.5 hover:bg-[#f1f5f9]">View Dependency Impact</button>
                  <button className="text-left border border-[#d1d9e0] text-[#1a3a5c] px-3 py-1.5 hover:bg-[#f1f5f9]">Raise Grievance</button>
                </>
              )}
              {dec.state === 'correction' && (
                <button onClick={onGoToE20} className="text-left border border-[#d1d9e0] text-[#1a3a5c] px-3 py-1.5 hover:bg-[#f1f5f9]">View Query / Correction (E20)</button>
              )}
            </div>
          </div>

          {/* Certificate / Document card (approved only) */}
          {dec.state === 'approved' && (
            <div className="bg-white border border-[#86efac]">
              <div className="px-3 py-2.5 border-b border-[#bbf7d0] bg-[#f0fdf4]">
                <p className="text-xs font-bold text-[#166534]">Certificate Issued</p>
              </div>
              <div className="px-3 py-3 text-xs space-y-1.5">
                <div>
                  <p className="text-[10px] text-[#94a3b8] uppercase tracking-wider">Certificate ID</p>
                  <p className="font-mono font-medium text-[#334155]">{dec.certId}</p>
                </div>
                <div>
                  <p className="text-[10px] text-[#94a3b8] uppercase tracking-wider">Valid Until</p>
                  <p className="font-medium text-[#334155]">{dec.expiryDate}</p>
                </div>
                <div>
                  <p className="text-[10px] text-[#94a3b8] uppercase tracking-wider">Document Centre</p>
                  <button onClick={onGoToE11} className="text-[#1a56db] hover:underline">DOC-003 in E11 →</button>
                </div>
              </div>
            </div>
          )}

          {/* Related records */}
          <div className="bg-white border border-[#e2e8f0]">
            <div className="px-3 py-2.5 border-b border-[#e8edf2]">
              <p className="text-xs font-bold text-[#1a3a5c]">Related Records</p>
            </div>
            <div className="px-3 py-3 flex flex-col gap-1.5 text-xs">
              <button onClick={onGoToE19} className="text-left text-[#1a56db] hover:underline">Application Detail (E19)</button>
              {dec.inspectionId && <button onClick={onGoToE22} className="text-left text-[#1a56db] hover:underline">Inspection — {dec.inspectionId} (E22)</button>}
              <button onClick={onGoToE11} className="text-left text-[#1a56db] hover:underline">Document Centre (E11)</button>
              <button onClick={() => onGoToE10('EST-001')} className="text-left text-[#1a56db] hover:underline">Requirement Detail (E10)</button>
              <button onClick={onGoToE09} className="text-left text-[#1a56db] hover:underline">Regulatory Journey (E09)</button>
              <button onClick={onGoToE13} className="text-left text-[#1a56db] hover:underline">Dependency Graph (E13)</button>
              {dec.state === 'correction' && <button onClick={onGoToE20} className="text-left text-[#1a56db] hover:underline">Query Response (E20)</button>}
              <button onClick={onGoToE24} className="text-left text-[#1a56db] hover:underline">Compliance Dashboard (E24)</button>
            </div>
          </div>
        </div>
      </div>
    </main>
  )
}

// ─── E22 — Inspection Centre ───────────────────────────────────────────────────

type InspectionStatus =
  | 'Required'
  | 'Awaiting Schedule'
  | 'Scheduled'
  | 'Completed'
  | 'Observation Raised'
  | 'Correction Submitted'
  | 'Re-inspection Required'
  | 'Resolved'

interface InspectionObservation {
  id: string
  description: string
  checklistItem: string
  evidenceRequired: string | null
  requiredCorrection: string
  responseState: 'Pending' | 'Submitted' | 'Accepted'
  dateRaised: string
}

interface InspectionChecklistItem {
  category: string
  items: string[]
}

interface InspectionRecord {
  id: string
  departments: string[]
  type: string
  relatedAppIds: string[]
  date: string
  time: string
  site: string
  status: InspectionStatus
  actionRequired: string | null
  coordinated: boolean
  prepRequirements: string[]
  documents: { id: string; name: string }[]
  checklist: InspectionChecklistItem[]
  observations: InspectionObservation[]
  reInspectionReason: string | null
}

