// ─── E32 — Grievances ────────────────────────────────────────────────────────

type GrievanceStatus = 'Raised' | 'Assigned' | 'Escalated' | 'Response' | 'Resolved' | 'Reopened'
type GrievanceReason = 'SLA breach' | 'Unresolved query' | 'Department delay' | 'Incorrect status' | 'Inspection delay' | 'Other'

interface Grievance {
  id: string
  reason: GrievanceReason
  description: string
  status: GrievanceStatus
  applicationId: string
  department: string
  service: string
  currentDesk: string
  submissionDate: string
  sla: string
  raisedDate: string
  assignedTo: string
  responses: Array<{ author: string; role: string; date: string; text: string }>
  escalationHistory: Array<{ date: string; from: string; to: string; reason: string }>
  resolution?: string
}

