type NotificationGroup = 'Action Required' | 'Upcoming' | 'Information' | 'Resolved'
type NotificationType = 'missing-doc' | 'expiry' | 'query' | 'correction' | 'resubmission' | 'approval' | 'rejection' | 'inspection' | 'sla' | 'dependency' | 'renewal' | 'compliance' | 'incentive' | 'claim' | 'reg-change' | 'business-change' | 'grievance'

