const notifGroupOrder: NotificationGroup[] = ['Action Required', 'Upcoming', 'Information', 'Resolved']
const notifGroupColors: Record<NotificationGroup, { header: string; dot: string }> = {
  'Action Required': { header: 'text-red-700', dot: 'bg-red-500' },
  'Upcoming':        { header: 'text-amber-700', dot: 'bg-amber-500' },
  'Information':     { header: 'text-blue-700', dot: 'bg-blue-500' },
  'Resolved':        { header: 'text-green-700', dot: 'bg-green-500' },
}

function E33NotificationCentrePage({ onNavigate, lang }: { onNavigate: (page: string) => void; lang: 'en' | 'mr' }) {
  const [notifications, setNotifications] = useState<AppNotification[]>(MOCK_NOTIFICATIONS)
  const [activeGroup, setActiveGroup] = useState<NotificationGroup | 'All'>('All')

  const t = {
    en: {
      title: 'Notification Centre',
      marathi: 'अधिसूचना केंद्र',
      subtitle: 'Centralised alerts across your business and applications.',
      markAllRead: 'Mark all as read',
      what: 'What happened',
      why: 'Why it matters',
      action: 'Action needed',
      due: 'Due',
      all: 'All',
      unread: 'unread',
    },
    mr: {
      title: 'अधिसूचना केंद्र',
      marathi: 'Notification Centre',
      subtitle: 'तुमच्या व्यवसाय आणि अर्जांमधील केंद्रीय सूचना.',
      markAllRead: 'सर्व वाचले म्हणून चिन्हांकित करा',
      what: 'काय झाले',
      why: 'हे का महत्त्वाचे आहे',
      action: 'आवश्यक कृती',
      due: 'देय',
      all: 'सर्व',
      unread: 'न वाचलेले',
    },
  }[lang]

  const markRead = (id: string) => setNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n))
  const markAllRead = () => setNotifications(prev => prev.map(n => ({ ...n, isRead: true })))
  const unreadCount = notifications.filter(n => !n.isRead).length

  const filtered = activeGroup === 'All' ? notifications : notifications.filter(n => n.group === activeGroup)
  const grouped = notifGroupOrder.reduce<Record<NotificationGroup, AppNotification[]>>((acc, g) => {
    acc[g] = filtered.filter(n => n.group === g)
    return acc
  }, {} as Record<NotificationGroup, AppNotification[]>)

  return (
    <main id="main-content" className="flex-1 bg-[#f8f9fb]" tabIndex={-1}>
      <div className="max-w-[900px] mx-auto px-6 py-5">
        <div className="mb-4">
          <Breadcrumb items={[{ label: 'Home', href: '#' }, { label: t.title }]} />
        </div>

        <div className="flex items-start justify-between gap-4 mb-5">
          <div>
            <h1 className="text-xl font-bold text-[#1a2533]">{t.title}</h1>
            <p className="text-sm text-[#6b7a8d] mt-0.5">{t.subtitle}</p>
          </div>
          <div className="flex items-center gap-3">
            {unreadCount > 0 && (
              <span className="text-xs font-semibold text-red-700 bg-red-50 border border-red-200 px-2.5 py-1 rounded-full">
                {unreadCount} {t.unread}
              </span>
            )}
            <button onClick={markAllRead} className="text-xs text-[#1a56db] hover:underline font-medium">{t.markAllRead}</button>
          </div>
        </div>

        {/* Group filter tabs */}
        <div role="tablist" aria-label="Notification groups" className="flex border-b border-[#d1d9e0] mb-5">
          {(['All', ...notifGroupOrder] as (NotificationGroup | 'All')[]).map(g => {
            const count = g === 'All' ? notifications.length : notifications.filter(n => n.group === g).length
            const unread = g === 'All' ? unreadCount : notifications.filter(n => n.group === g && !n.isRead).length
            return (
              <button key={g} role="tab" aria-selected={activeGroup === g}
                onClick={() => setActiveGroup(g)}
                className={`px-4 py-2.5 text-sm font-medium border-b-2 -mb-px transition-colors whitespace-nowrap flex items-center gap-1.5
                  ${activeGroup === g ? 'border-[#1a3a5c] text-[#1a3a5c]' : 'border-transparent text-[#6b7a8d] hover:text-[#374151] hover:border-[#d1d9e0]'}`}
              >
                {g}
                <span className="text-xs text-[#9aa5b4]">({count})</span>
                {unread > 0 && <span className="w-2 h-2 bg-red-500 rounded-full" aria-label={`${unread} unread`} />}
              </button>
            )
          })}
        </div>

        {/* Notifications grouped */}
        <div className="space-y-6">
          {notifGroupOrder.map(group => {
            const items = grouped[group]
            if (!items || items.length === 0) return null
            const cfg = notifGroupColors[group]
            return (
              <section key={group} aria-labelledby={`notif-group-${group}`}>
                <h2 id={`notif-group-${group}`} className={`text-xs font-bold uppercase tracking-wider mb-3 flex items-center gap-2 ${cfg.header}`}>
                  <span className={`w-2 h-2 rounded-full ${cfg.dot}`} aria-hidden="true" />
                  {group}
                  <span className="font-normal text-[#9aa5b4]">({items.length})</span>
                </h2>
                <div className="space-y-2">
                  {items.map(n => {
                    const TypeIcon = notifTypeIcon[n.type]
                    return (
                      <article key={n.id} className={`bg-white border rounded p-4 transition-colors ${n.isRead ? 'border-[#d1d9e0]' : 'border-[#1a56db] ring-1 ring-[#ebf3ff]'}`}
                        onClick={() => markRead(n.id)} role="article" aria-label={n.title}>
                        <div className="flex items-start gap-3">
                          <div className={`shrink-0 w-8 h-8 rounded-full flex items-center justify-center mt-0.5 ${n.isRead ? 'bg-[#f8f9fb] text-[#9aa5b4]' : 'bg-blue-50 text-[#1a56db]'}`}>
                            <TypeIcon />
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="flex items-start justify-between gap-3">
                              <h3 className={`text-sm font-semibold leading-snug ${n.isRead ? 'text-[#374151]' : 'text-[#1a2533]'}`}>{n.title}</h3>
                              <div className="flex items-center gap-2 shrink-0">
                                {!n.isRead && <span className="w-2 h-2 bg-[#1a56db] rounded-full shrink-0" aria-label="Unread" />}
                                <span className="text-xs text-[#9aa5b4]">{n.timestamp}</span>
                              </div>
                            </div>
                            <div className="mt-2 grid grid-cols-1 md:grid-cols-3 gap-2 text-xs">
                              <div>
                                <p className="text-[#9aa5b4] font-medium uppercase tracking-wide">{t.why}</p>
                                <p className="text-[#4a5568] mt-0.5">{n.why}</p>
                              </div>
                              <div>
                                <p className="text-[#9aa5b4] font-medium uppercase tracking-wide">{t.action}</p>
                                <p className="text-[#4a5568] mt-0.5">{n.action}</p>
                              </div>
                              <div>
                                <p className="text-[#9aa5b4] font-medium uppercase tracking-wide">{t.due}</p>
                                <p className={`mt-0.5 font-medium ${n.group === 'Action Required' ? 'text-red-700' : 'text-[#4a5568]'}`}>{n.due}</p>
                              </div>
                            </div>
                            <div className="mt-3">
                              <button
                                onClick={(e) => { e.stopPropagation(); markRead(n.id); onNavigate(n.ctaTarget) }}
                                className="text-xs text-[#1a56db] hover:underline font-medium focus:outline-none focus-visible:underline"
                              >
                                {n.ctaLabel} →
                              </button>
                            </div>
                          </div>
                        </div>
                      </article>
                    )
                  })}
                </div>
              </section>
            )
          })}
        </div>
      </div>
    </main>
  )
}

// ─── E34 — Regulatory Assistant ──────────────────────────────────────────────

type RegEntryPoint = 'requirement' | 'document' | 'application' | 'query' | 'compliance' | 'incentive' | 'reg-change' | 'general'

interface RegAssistantContext {
  entryPoint: RegEntryPoint
  recordId?: string
  recordName?: string
  department?: string
  service?: string
  grReference?: string
  initialQuestion?: string
}

interface RegAssistantMessage {
  role: 'user' | 'assistant' | 'context'
  text: string
  source?: string
  clause?: string
  effectiveDate?: string
  related?: string
  needsVerification?: boolean
  uncertainty?: string
}

