// Match a question to a response
function matchRegResponse(text: string, context: RegAssistantContext | null): RegAssistantMessage {
  const q = text.toLowerCase()
  if (q.includes('marathi') || q.includes('मराठी') || q.includes('explain in marathi')) return REG_MOCK_RESPONSES[8]
  if (q.includes('approval required') || q.includes('why is this approval') || q.includes('why is this requirement') || q.includes('why is this applicable')) return REG_MOCK_RESPONSES[0]
  if ((q.includes('document required') || q.includes('why is this doc')) && !q.includes('contain') && !q.includes('obtain')) return REG_MOCK_RESPONSES[1]
  if (q.includes('contain') || q.includes('should this document')) return REG_MOCK_RESPONSES[2]
  if (q.includes('gr') || q.includes('rule') || q.includes('government resolution') || q.includes('which rule')) return REG_MOCK_RESPONSES[3]
  if (q.includes('obtain') || q.includes('where can') || q.includes('where do')) return REG_MOCK_RESPONSES[4]
  if (q.includes('changed') || q.includes('what changed') || q.includes('what exact')) return REG_MOCK_RESPONSES[5]
  if (q.includes('query mean') || q.includes('department query') || q.includes('deficiency') || q.includes('respond')) return REG_MOCK_RESPONSES[6]
  if (q.includes('section') || q.includes('application') || q.includes('which section')) return REG_MOCK_RESPONSES[7]

  // Context-aware fallback
  if (context?.entryPoint === 'requirement') return REG_MOCK_RESPONSES[0]
  if (context?.entryPoint === 'document') return REG_MOCK_RESPONSES[1]
  if (context?.entryPoint === 'query') return REG_MOCK_RESPONSES[6]
  if (context?.entryPoint === 'reg-change') return REG_MOCK_RESPONSES[5]

  return {
    role: 'assistant',
    text: 'I can help with questions about regulatory requirements, documents, GRs, departmental queries, and regulatory changes related to your applications. Please rephrase your question, or select one of the suggested questions shown when the conversation starts.\n\nNote: I cannot approve, reject, or substitute a department decision. When applicability is unclear, I will always mark the response as Needs Verification.',
    needsVerification: false,
  }
}

// The "Ask Regulatory Assistant" trigger button — used inline on entry-point pages
function RegAssistantTrigger({ onClick, label, lang, size = 'sm' }: {
  onClick: () => void
  label?: string
  lang: 'en' | 'mr'
  size?: 'sm' | 'xs'
}) {
  const defaultLabel = lang === 'mr' ? 'नियामक सहाय्यक' : 'Regulatory Assistant'
  const cls = size === 'xs'
    ? 'flex items-center gap-1.5 text-[11px] border border-[#d1d9e0] text-[#1a3a5c] px-2.5 py-1 rounded hover:bg-[#f0f4f8] font-medium transition-colors'
    : 'flex items-center gap-2 text-xs border border-[#d1d9e0] text-[#1a3a5c] px-3 py-1.5 rounded hover:bg-[#f0f4f8] font-medium transition-colors'
  return (
    <button onClick={onClick} className={cls} aria-label="Open Regulatory Assistant">
      <Icon.Shield />
      {label ?? defaultLabel}
    </button>
  )
}

function E34RegAssistantDrawer({
  isOpen,
  onClose,
  context,
  lang,
}: {
  isOpen: boolean
  onClose: () => void
  context: RegAssistantContext | null
  lang: 'en' | 'mr'
}) {
  const [messages, setMessages] = useState<RegAssistantMessage[]>([])
  const [input, setInput] = useState('')
  const [loading, setLoading] = useState(false)
  const [sessionKey, setSessionKey] = useState(0)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  // Reset session when context changes
  useEffect(() => {
    setMessages([])
    setInput('')
    setSessionKey(k => k + 1)
  }, [context?.entryPoint, context?.recordId])

  // Auto-inject initial question when drawer opens with a context
  useEffect(() => {
    if (isOpen && context?.initialQuestion && messages.length === 0) {
      const timer = setTimeout(() => sendMessage(context.initialQuestion!), 300)
      return () => clearTimeout(timer)
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, sessionKey])

  useEffect(() => {
    if (isOpen) {
      setTimeout(() => inputRef.current?.focus(), 100)
    }
  }, [isOpen])

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages, loading])

  const t = {
    en: {
      title: 'Regulatory Assistant',
      subtitle: 'Guidance only — not a statutory decision',
      context: 'Context',
      placeholder: 'Ask a regulatory question…',
      send: 'Send',
      suggested: 'Suggested questions for this record',
      suggestedGeneral: 'Suggested questions',
      consulting: 'Consulting regulations…',
      disclaimer: 'This assistant retrieves and explains regulatory information from official sources. It does not approve, reject, or substitute a department decision. When applicability is uncertain, it will say so explicitly.',
      noApproval: 'Cannot approve, reject, or modify obligations.',
      needsVerification: 'Needs Verification',
      needsVerificationDesc: 'Confirm with the relevant authority before acting on this guidance.',
      uncertainty: 'Uncertainty',
      source: 'Source',
      clause: 'Clause / Section',
      effective: 'Effective Date',
      related: 'Related Requirement',
      clearSession: 'New session',
    },
    mr: {
      title: 'नियामक सहाय्यक',
      subtitle: 'केवळ मार्गदर्शन — वैधानिक निर्णय नाही',
      context: 'संदर्भ',
      placeholder: 'नियामक प्रश्न विचारा…',
      send: 'पाठवा',
      suggested: 'या नोंदीसाठी सुचवलेले प्रश्न',
      suggestedGeneral: 'सुचवलेले प्रश्न',
      consulting: 'नियमांचा आढावा घेत आहे…',
      disclaimer: 'हा सहाय्यक अधिकृत स्रोतांमधून नियामक माहिती पुनर्प्राप्त आणि स्पष्ट करतो. तो विभागाचा निर्णय मंजूर, नाकारू किंवा बदलू शकत नाही.',
      noApproval: 'दायित्वे मंजूर, नाकारू किंवा सुधारू शकत नाही.',
      needsVerification: 'पडताळणी आवश्यक',
      needsVerificationDesc: 'या मार्गदर्शनावर कार्य करण्यापूर्वी संबंधित प्राधिकरणाशी खात्री करा.',
      uncertainty: 'अनिश्चितता',
      source: 'स्रोत',
      clause: 'कलम / विभाग',
      effective: 'प्रभावी दिनांक',
      related: 'संबंधित आवश्यकता',
      clearSession: 'नवीन सत्र',
    },
  }[lang]

  const entryPoint = context?.entryPoint ?? 'general'
  const suggestedQs = REG_SUGGESTED_QUESTIONS[entryPoint]

  const entryPointLabel: Record<RegEntryPoint, { en: string; mr: string }> = {
    requirement:  { en: 'Requirement', mr: 'आवश्यकता' },
    document:     { en: 'Document', mr: 'दस्तऐवज' },
    application:  { en: 'Application', mr: 'अर्ज' },
    query:        { en: 'Query / Deficiency', mr: 'चौकशी / कमतरता' },
    compliance:   { en: 'Compliance', mr: 'अनुपालन' },
    incentive:    { en: 'Incentive / Scheme', mr: 'प्रोत्साहन / योजना' },
    'reg-change': { en: 'Regulatory Change', mr: 'नियामक बदल' },
    general:      { en: 'General', mr: 'सामान्य' },
  }

  function sendMessage(text: string) {
    if (!text.trim() || loading) return
    const userMsg: RegAssistantMessage = { role: 'user', text }
    setMessages(prev => [...prev, userMsg])
    setInput('')
    setLoading(true)
    setTimeout(() => {
      const response = matchRegResponse(text, context)
      setMessages(prev => [...prev, response])
      setLoading(false)
    }, 900 + Math.random() * 400)
  }

  if (!isOpen) return null

  const contextHasRecord = context && context.recordName
  const epLabel = entryPointLabel[entryPoint][lang]

  return (
    <div className="fixed inset-0 z-50 flex justify-end" role="dialog" aria-modal="true" aria-labelledby="reg-assistant-title">
      <div className="absolute inset-0 bg-black/25 backdrop-blur-[1px]" onClick={onClose} aria-hidden="true" />
      <div className="relative bg-white w-[460px] max-w-[95vw] h-full shadow-2xl flex flex-col border-l border-[#d1d9e0]">

        {/* ── Header ── */}
        <div className="bg-[#1a3a5c] text-white px-4 pt-4 pb-3 shrink-0">
          <div className="flex items-start justify-between gap-3">
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 mb-0.5">
                <span className="text-white/80 shrink-0"><Icon.Shield /></span>
                <h2 id="reg-assistant-title" className="text-sm font-bold leading-tight">{t.title}</h2>
                <span className="text-[10px] bg-white/15 border border-white/20 px-1.5 py-0.5 rounded font-mono text-white/70 shrink-0">RAG</span>
              </div>
              <p className="text-xs text-white/60 leading-tight">{t.subtitle}</p>

              {/* Context pill */}
              {contextHasRecord && (
                <div className="mt-2 flex items-start gap-2">
                  <span className="text-[10px] text-white/40 uppercase tracking-wider font-medium shrink-0 mt-0.5">{t.context}:</span>
                  <div className="flex flex-wrap gap-1">
                    <span className="text-[11px] bg-white/10 border border-white/15 px-2 py-0.5 rounded text-white/80 font-medium">{epLabel}</span>
                    <span className="text-[11px] bg-white/10 border border-white/15 px-2 py-0.5 rounded text-white/70 truncate max-w-[240px]">{context.recordName}</span>
                  </div>
                </div>
              )}
              {!contextHasRecord && context && (
                <div className="mt-1.5">
                  <span className="text-[11px] bg-white/10 border border-white/15 px-2 py-0.5 rounded text-white/70">{epLabel}</span>
                </div>
              )}
            </div>
            <div className="flex items-start gap-1 shrink-0">
              {messages.length > 0 && (
                <button onClick={() => setMessages([])} className="text-[10px] text-white/50 hover:text-white/80 px-2 py-1 rounded hover:bg-white/10 transition-colors">{t.clearSession}</button>
              )}
              <button onClick={onClose} className="p-1 text-white/60 hover:text-white transition-colors" aria-label="Close Regulatory Assistant">
                <Icon.X />
              </button>
            </div>
          </div>
        </div>

        {/* ── Boundary notice ── */}
        <div className="bg-amber-50 border-b border-amber-200 px-4 py-2 flex items-start gap-2 shrink-0">
          <span className="text-amber-500 shrink-0 mt-px"><Icon.Warning /></span>
          <p className="text-[11px] text-amber-800 leading-snug">{t.disclaimer}</p>
        </div>

        {/* ── Messages area ── */}
        <div className="flex-1 overflow-y-auto px-4 py-3 space-y-3 bg-[#f8f9fb]">

          {/* Initial state — suggested questions */}
          {messages.length === 0 && !loading && (
            <div className="space-y-2.5">
              <p className="text-[10px] text-[#9aa5b4] font-bold uppercase tracking-wider">
                {contextHasRecord ? t.suggested : t.suggestedGeneral}
              </p>
              <div className="space-y-1.5">
                {suggestedQs.map(q => (
                  <button key={q} onClick={() => sendMessage(q)}
                    className="w-full text-left text-xs text-[#1a56db] bg-white hover:bg-[#ebf3ff] border border-[#d1d9e0] hover:border-blue-200 rounded px-3 py-2 transition-colors leading-snug">
                    {q}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Message thread */}
          {messages.map((msg, i) => (
            <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              {msg.role === 'user' ? (
                <div className="bg-[#1a3a5c] text-white text-xs rounded-2xl rounded-tr-sm px-3.5 py-2.5 max-w-[85%] leading-relaxed">
                  {msg.text}
                </div>
              ) : (
                <div className="bg-white border border-[#d1d9e0] rounded-2xl rounded-tl-sm p-3.5 max-w-[100%] space-y-2.5 shadow-sm">
                  {/* Answer */}
                  <p className="text-xs text-[#1a2533] leading-relaxed whitespace-pre-wrap">{msg.text}</p>

                  {/* Needs Verification callout */}
                  {msg.needsVerification && (
                    <div className="flex items-start gap-2 bg-amber-50 border border-amber-200 rounded-lg p-2.5">
                      <span className="text-amber-500 shrink-0 mt-px"><Icon.Warning /></span>
                      <div>
                        <p className="text-[11px] font-bold text-amber-800">{t.needsVerification}</p>
                        <p className="text-[11px] text-amber-700 mt-0.5">{msg.uncertainty || t.needsVerificationDesc}</p>
                      </div>
                    </div>
                  )}

                  {/* Structured citation block */}
                  {(msg.source || msg.clause || msg.effectiveDate || msg.related) && (
                    <div className="border border-[#e8edf2] rounded-lg overflow-hidden bg-[#fafbfc]">
                      <div className="px-3 py-1.5 bg-[#f0f4f8] border-b border-[#e8edf2]">
                        <p className="text-[10px] font-bold text-[#6b7a8d] uppercase tracking-wider">Regulatory Reference</p>
                      </div>
                      <div className="px-3 py-2.5 space-y-2">
                        {msg.source && (
                          <div className="flex gap-2">
                            <span className="text-[10px] font-bold text-[#9aa5b4] uppercase tracking-wider w-20 shrink-0 mt-px">{t.source}</span>
                            <span className="text-[11px] text-[#374151] leading-snug flex-1">{msg.source}</span>
                          </div>
                        )}
                        {msg.clause && (
                          <div className="flex gap-2">
                            <span className="text-[10px] font-bold text-[#9aa5b4] uppercase tracking-wider w-20 shrink-0 mt-px">{t.clause}</span>
                            <span className="text-[11px] text-[#374151] leading-snug flex-1">{msg.clause}</span>
                          </div>
                        )}
                        {msg.effectiveDate && (
                          <div className="flex gap-2">
                            <span className="text-[10px] font-bold text-[#9aa5b4] uppercase tracking-wider w-20 shrink-0 mt-px">{t.effective}</span>
                            <span className="text-[11px] text-[#374151] leading-snug flex-1">{msg.effectiveDate}</span>
                          </div>
                        )}
                        {msg.related && (
                          <div className="flex gap-2">
                            <span className="text-[10px] font-bold text-[#9aa5b4] uppercase tracking-wider w-20 shrink-0 mt-px">{t.related}</span>
                            <span className="text-[11px] text-[#374151] leading-snug flex-1">{msg.related}</span>
                          </div>
                        )}
                      </div>
                    </div>
                  )}

                  {/* Inline quick follow-up chips if this isn't the last message */}
                  {i === messages.length - 1 && !loading && (
                    <div className="flex flex-wrap gap-1.5 pt-0.5">
                      {suggestedQs.slice(0, 3).filter(q => !messages.some(m => m.role === 'user' && m.text === q)).map(q => (
                        <button key={q} onClick={() => sendMessage(q)}
                          className="text-[10px] text-[#1a56db] bg-[#ebf3ff] hover:bg-blue-100 border border-blue-200 rounded-full px-2 py-0.5 transition-colors leading-snug">
                          {q}
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>
          ))}

          {/* Loading indicator */}
          {loading && (
            <div className="flex justify-start">
              <div className="bg-white border border-[#d1d9e0] rounded-2xl rounded-tl-sm px-4 py-3 flex items-center gap-2 text-xs text-[#6b7a8d] shadow-sm">
                <Icon.Loader />
                {t.consulting}
              </div>
            </div>
          )}

          <div ref={messagesEndRef} />
        </div>

        {/* ── Input ── */}
        <div className="border-t border-[#d1d9e0] bg-white px-3 pt-2.5 pb-3 shrink-0">
          <p className="text-[10px] text-[#b0bcc9] mb-2">{t.noApproval}</p>
          <div className="flex gap-2">
            <input
              ref={inputRef}
              type="text"
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={e => {
                if (e.key === 'Enter' && !e.shiftKey && !loading) {
                  e.preventDefault()
                  sendMessage(input)
                }
              }}
              placeholder={t.placeholder}
              className={`${inputDefault} flex-1 text-xs`}
              aria-label={t.placeholder}
              disabled={loading}
            />
            <button
              onClick={() => sendMessage(input)}
              disabled={!input.trim() || loading}
              className="bg-[#1a3a5c] text-white text-xs font-semibold px-3.5 py-2 rounded hover:bg-[#0f2540] transition-colors disabled:opacity-40 disabled:cursor-not-allowed shrink-0"
            >
              {t.send}
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

// Standalone E34 page — accessible from dev toolbar and Help icon
function E34RegAssistantPage({ onBack, lang }: { onBack: () => void; lang: 'en' | 'mr' }) {
  const [drawerOpen, setDrawerOpen] = useState(true)
  const t = {
    en: { title: 'Regulatory Assistant', intro: 'Ask questions about requirements, documents, GRs, departmental queries, and regulatory changes. The assistant is open on the right.', open: 'Open Regulatory Assistant' },
    mr: { title: 'नियामक सहाय्यक', intro: 'आवश्यकता, दस्तऐवज, GR, विभागीय चौकशी आणि नियामक बदलांबद्दल प्रश्न विचारा.', open: 'नियामक सहाय्यक उघडा' },
  }[lang]
  const ctx: RegAssistantContext = { entryPoint: 'general' }
  return (
    <main id="main-content" className="flex-1 bg-[#f8f9fb]" tabIndex={-1}>
      <div className="max-w-[960px] mx-auto px-6 py-5">
        <div className="mb-4">
          <Breadcrumb items={[{ label: 'Home', href: '#' }, { label: t.title }]} />
        </div>
        <div className="bg-white border border-[#d1d9e0] rounded p-8 text-center">
          <div className="w-12 h-12 rounded-full bg-[#f0f4f8] border border-[#d1d9e0] flex items-center justify-center text-[#1a3a5c] mx-auto mb-4">
            <Icon.Shield />
          </div>
          <h1 className="text-base font-semibold text-[#1a2533] mb-2">{t.title}</h1>
          <p className="text-sm text-[#6b7a8d] max-w-sm mx-auto mb-5">{t.intro}</p>
          <div className="flex flex-wrap gap-3 justify-center text-xs text-[#6b7a8d] mb-6">
            {['Requirement Detail', 'Document Detail', 'Application', 'Query', 'Compliance', 'Incentive / Scheme', 'Regulatory Change'].map(ep => (
              <span key={ep} className="bg-[#f0f4f8] border border-[#d1d9e0] rounded px-3 py-1">{ep}</span>
            ))}
          </div>
          <button onClick={() => setDrawerOpen(true)} className="bg-[#1a3a5c] text-white text-sm font-medium px-5 py-2 rounded hover:bg-[#0f2540] transition-colors">
            {t.open}
          </button>
        </div>
      </div>
      <E34RegAssistantDrawer isOpen={drawerOpen} onClose={() => { setDrawerOpen(false); onBack() }} context={ctx} lang={lang} />
    </main>
  )
}

// ─── E00 — Entrepreneur Command Centre ───────────────────────────────────────

function E00CommandCentrePage({
  cteApproved,
  lang,
  onGoToJourney,
  onGoToDependency,
  onGoToDocCentre,
  onGoToApplication,
  onGoToQuery,
  onGoToCompliance,
  onGoToComplianceDetail,
  onGoToInspection,
  onGoToIncentives,
  onGoToIncentiveDetail,
  onGoToRegChanges,
  onGoToNotifications,
  onGoToGrievances,
  onGoToReqDetail,
  onOpenRegAssistant,
}: {
  cteApproved: boolean
  lang: 'en' | 'mr'
  onGoToJourney: () => void
  onGoToDependency: () => void
  onGoToDocCentre: () => void
  onGoToApplication: (id: string) => void
  onGoToQuery: () => void
  onGoToCompliance: () => void
  onGoToComplianceDetail: (id: string) => void
  onGoToInspection: () => void
  onGoToIncentives: () => void
  onGoToIncentiveDetail: (id: string) => void
  onGoToRegChanges: () => void
  onGoToNotifications: () => void
  onGoToGrievances: () => void
  onGoToReqDetail: (id: string) => void
  onOpenRegAssistant?: (ctx: RegAssistantContext) => void
})
{
  // ── Data derivations ────────────────────────────────────────────────────────
  const nodes = buildJourneyNodes(cteApproved)
  const stageStates = STAGES.map(s => ({ ...s, state: stageDisplayState(nodes, s.key) }))
  const currentStageIdx = stageStates.findIndex(s => ['In Progress', 'Action Required', 'Ready'].includes(s.state))
  const currentStage = currentStageIdx >= 0 ? stageStates[currentStageIdx] : null

  const reqApplicable = nodes.filter(n => n.applicability !== 'not-applicable')
  const reqApproved   = reqApplicable.filter(n => n.displayState === 'approved').length
  const reqInProgress = reqApplicable.filter(n => n.displayState === 'in-progress' || n.displayState === 'under-review').length
  const reqActionReqd = reqApplicable.filter(n => n.displayState === 'action-required').length

  const actionNotifs  = MOCK_NOTIFICATIONS.filter(n => n.group === 'Action Required')
  const upcomingNotifs= MOCK_NOTIFICATIONS.filter(n => n.group === 'Upcoming')
  const infoNotifs    = MOCK_NOTIFICATIONS.filter(n => n.group === 'Information')

  const complianceActionCount = COMPLIANCE_OBLIGATIONS.filter(o => o.status === 'Action Required').length
  const complianceDueSoon     = COMPLIANCE_OBLIGATIONS.filter(o => o.status === 'Due Soon').length
  const complianceDue         = COMPLIANCE_OBLIGATIONS.filter(o => o.status === 'Due Soon' || o.status === 'Action Required' || o.status === 'Overdue').length

  const incentivesEligible   = INCENTIVE_SCHEMES.filter(s => s.eligState === 'Appears eligible from available data').length
  const incentivesVerify     = INCENTIVE_SCHEMES.filter(s => s.eligState === 'Needs Verification').length

  const regChangesAction     = REGULATORY_CHANGES.filter(r => r.impactCategory !== 'No action')

  // ── Stage state visual config ─────────────────────────────────────────────
  const stageCfg: Record<string, { bg: string; text: string; border: string; dot: string; check: string }> = {
    'Complete':        { bg: 'bg-[#f0fdf4]',  text: 'text-[#166534]',  border: 'border-[#86efac]',  dot: 'bg-[#16a34a]',  check: '✓' },
    'In Progress':     { bg: 'bg-[#ede9fe]',  text: 'text-[#3730a3]',  border: 'border-[#a5b4fc]',  dot: 'bg-[#6366f1]',  check: '◎' },
    'Action Required': { bg: 'bg-[#fef3c7]',  text: 'text-[#92400e]',  border: 'border-[#fde68a]',  dot: 'bg-[#d97706]',  check: '!' },
    'Ready':           { bg: 'bg-[#ebf3ff]',  text: 'text-[#1a3a5c]',  border: 'border-[#93c5fd]',  dot: 'bg-[#1a56db]',  check: '▶' },
    'Waiting':         { bg: 'bg-[#f8f9fb]',  text: 'text-[#6b7a8d]',  border: 'border-[#d1d9e0]',  dot: 'bg-[#9aa5b4]',  check: '⏸' },
    'Upcoming':        { bg: 'bg-[#f8f9fb]',  text: 'text-[#9aa5b4]',  border: 'border-[#e2e8f0]',  dot: 'bg-[#d1d9e0]',  check: '—' },
  }

  // ── Applications ──────────────────────────────────────────────────────────
  const APPLICATIONS = [
    { id: 'APP-MPCB-2026-4892', dept: 'MPCB',  service: 'Consent to Establish (CTE)',    desk: 'Technical Review — Environment Officer', status: 'Under Review',  statusCls: 'bg-[#ede9fe] text-[#3730a3] border-[#a5b4fc]', sla: '12 days overdue', slaRed: true,  actionLabel: 'Track',   nav: 'track-mpcb' },
    { id: 'APP-FAC-2026-3371',  dept: 'DISH',   service: 'Factory / Occupier Registration',desk: 'Inspector of Factories — Pune Circle',    status: 'Query Raised',  statusCls: 'bg-[#fef3c7] text-[#92400e] border-[#fde68a]', sla: '9 days remaining',slaRed: false, actionLabel: 'Respond', nav: 'query' },
    { id: 'APP-MIDC-2026-1190', dept: 'MIDC',   service: 'MIDC Plot Lease Agreement',      desk: 'N/A — Approved',                          status: 'Approved',      statusCls: 'bg-[#f0fdf4] text-[#166534] border-[#86efac]', sla: 'Completed',       slaRed: false, actionLabel: 'View',    nav: 'track-midc' },
  ]

  // ── Actions required ──────────────────────────────────────────────────────
  const ACTIONS = [
    { id: 'ACT-001', urgent: true,  label: 'Respond to DISH query — Factory Registration',   sub: 'Boiler capacity certificate required · Deadline 30 Sep 2026', cta: 'Respond to Query',  nav: 'query',   icon: <Icon.AlertCircle /> },
    { id: 'ACT-002', urgent: true,  label: 'Upload IBR Certificate — Document Centre',        sub: 'Required to unblock APP-FAC-2026-3371 · Deadline 30 Sep 2026',cta: 'Upload Document',   nav: 'doc',     icon: <Icon.Upload /> },
    { id: 'ACT-003', urgent: false, label: 'Submit ETP Commissioning Report — MPCB',          sub: 'CPL-001 · Action Required · Due 09 Nov 2026',                  cta: 'View Compliance',   nav: 'cpl-001', icon: <Icon.Warning /> },
    { id: 'ACT-004', urgent: false, label: 'Hazardous Waste Manifest Records — MPCB',         sub: 'CPL-002 · Ongoing obligation · Action Required',               cta: 'View Compliance',   nav: 'cpl-002', icon: <Icon.Warning /> },
    { id: 'ACT-005', urgent: false, label: 'SLA breach escalation pending — MPCB CTE',        sub: 'GRV-2026-0014 · Escalated · 42 days overdue',                 cta: 'View Grievance',    nav: 'grievance',icon: <Icon.AlertCircle /> },
  ]

  // ── Upcoming ──────────────────────────────────────────────────────────────
  const UPCOMING_ITEMS = [
    { date: '30 Sep 2026', days: 7,  label: 'DISH query response deadline',             type: 'Deadline',   urgent: true,  nav: 'query',      dotCls: 'bg-[#ef4444]',  textCls: 'text-[#b91c1c]' },
    { date: '05 Oct 2026', days: 12, label: 'DISH Factory Inspection — Chakan Unit',   type: 'Inspection', urgent: false, nav: 'inspection', dotCls: 'bg-[#f97316]',  textCls: 'text-[#c2410c]' },
    { date: '09 Nov 2026', days: 47, label: 'ETP Commissioning Report — MPCB (CPL-001)', type: 'Compliance', urgent: false, nav: 'cpl-001',    dotCls: 'bg-[#d97706]',  textCls: 'text-[#92400e]' },
    { date: '31 Dec 2026', days: 99, label: 'MPCB CTO Renewal deadline',               type: 'Renewal',    urgent: false, nav: 'compliance', dotCls: 'bg-[#6366f1]',  textCls: 'text-[#3730a3]' },
    { date: '31 Mar 2027', days: 189,label: 'Annual Environmental Audit — MPCB',       type: 'Compliance', urgent: false, nav: 'compliance', dotCls: 'bg-[#d97706]',  textCls: 'text-[#92400e]' },
    { date: 'Oct–Mar 2027',days: 120,label: 'PSI 2019 Claim CLM-2027-002 — Electricity Duty', type: 'Claim',  urgent: false, nav: 'incentives', dotCls: 'bg-[#16a34a]',  textCls: 'text-[#15803d]' },
  ]

  // ── Recent activity ───────────────────────────────────────────────────────
  const ACTIVITY = [
    { ts: '2 hr ago',   text: 'SLA breach alert — MPCB CTE (APP-MPCB-2026-4892) overdue by 12 days',        type: 'alert',      nav: 'grievance' },
    { ts: '1 day ago',  text: 'Query raised by DISH Inspector — Factory Registration, boiler cert required', type: 'query',      nav: 'query' },
    { ts: '2 days ago', text: 'Inspection confirmed by DISH — 05 Oct 2026, 10:00 AM, Chakan Unit',           type: 'inspection', nav: 'inspection' },
    { ts: '5 days ago', text: 'MIDC Plot Lease Agreement approved — APP-MIDC-2026-1190',                      type: 'approval',   nav: 'track-midc' },
    { ts: '8 days ago', text: 'MPCB effluent discharge norms updated — regulatory change logged (RC-2026-001)', type: 'reg',     nav: 'reg-change' },
    { ts: '12 days ago',text: 'Grievance GRV-2026-0014 escalated — MPCB CTE no response in 7 working days',  type: 'alert',      nav: 'grievance' },
    { ts: '13 days ago',text: 'Grievance GRV-2026-0003 resolved — MIDC portal status corrected',             type: 'resolved',   nav: 'grievance' },
  ]

  const activityDot: Record<string, string> = {
    alert: 'bg-[#ef4444]', query: 'bg-[#d97706]', inspection: 'bg-[#f97316]',
    approval: 'bg-[#16a34a]', reg: 'bg-[#6366f1]', resolved: 'bg-[#22c55e]',
  }

  function handleAppNav(nav: string) {
    if (nav === 'query') onGoToQuery()
    else onGoToApplication(nav.replace('track-', '') === nav ? nav : '')
  }

  function handleActionNav(nav: string) {
    if (nav === 'query') onGoToQuery()
    else if (nav === 'doc') onGoToDocCentre()
    else if (nav === 'grievance') onGoToGrievances()
    else if (nav === 'cpl-001') onGoToComplianceDetail('CPL-001')
    else if (nav === 'cpl-002') onGoToComplianceDetail('CPL-002')
    else onGoToCompliance()
  }

  function handleUpcomingNav(nav: string) {
    if (nav === 'inspection') onGoToInspection()
    else if (nav === 'query') onGoToQuery()
    else if (nav === 'compliance' || nav === 'cpl-001') onGoToCompliance()
    else if (nav === 'incentives') onGoToIncentives()
    else onGoToCompliance()
  }

  function handleNotifNav(n: AppNotification) {
    const t = n.ctaTarget
    if (t === 'e20-query') onGoToQuery()
    else if (t === 'e11-doc-centre') onGoToDocCentre()
    else if (t === 'e22-inspection') onGoToInspection()
    else if (t === 'e24-compliance') onGoToCompliance()
    else if (t === 'e32-grievances') onGoToGrievances()
    else if (t === 'e29-reg-change') onGoToRegChanges()
    else if (t === 'e19-detail') onGoToApplication(n.applicationId || '')
    else if (t === 'e33-notifications') onGoToNotifications()
    else onGoToNotifications()
  }

  return (
    <main id="main-content" className="flex-1 bg-[#f8f9fb]" tabIndex={-1}>

      {/* ── Selected Project Context Banner ─────────────────────────────────── */}
      <div className="bg-[#1a3a5c] border-b border-[#0f2540]">
        <div className="max-w-[1320px] mx-auto px-6 py-4">
          <div className="flex flex-wrap items-start justify-between gap-4">
            <div className="flex items-start gap-4">
              <div className="w-10 h-10 bg-[#0f2540] border border-[#2d5a8e] flex items-center justify-center shrink-0">
                <Icon.Building />
              </div>
              <div>
                <div className="flex items-center gap-2 flex-wrap">
                  <h1 className="text-base font-bold text-white leading-tight">ABC Pharma Pvt Ltd</h1>
                  <span className="text-[10px] font-bold bg-[#6366f1] text-white px-2 py-0.5 tracking-wider uppercase">Pre-Operation</span>
                  {actionNotifs.length > 0 && (
                    <span className="text-[10px] font-bold bg-[#ef4444] text-white px-2 py-0.5 tracking-wider uppercase">{actionNotifs.length} Actions Required</span>
                  )}
                </div>
                <p className="text-xs text-[#93c5fd] mt-0.5">Pharmaceutical Manufacturing Unit · Chakan Industrial Area Phase II, Thane</p>
                <div className="flex items-center gap-4 mt-1.5 flex-wrap">
                  <span className="text-[10px] text-[#7dd3fc]">UDYAM-MH-25-0082741</span>
                  <span className="text-[#2d5a8e]">·</span>
                  <span className="text-[10px] text-[#7dd3fc]">GSTIN: 27AABCS0750C1Z5</span>
                  <span className="text-[#2d5a8e]">·</span>
                  <span className="text-[10px] text-[#7dd3fc]">Registered 14 Apr 2026</span>
                </div>
              </div>
            </div>
            <div className="flex items-center gap-2 shrink-0">
              {onOpenRegAssistant && (
                <RegAssistantTrigger lang={lang} size="sm"
                  onClick={() => onOpenRegAssistant({ entryPoint: 'general', initialQuestion: 'What are my most urgent actions right now?' })}
                />
              )}
              <button onClick={onGoToNotifications} className="flex items-center gap-1.5 text-xs bg-[#0f2540] border border-[#2d5a8e] text-[#93c5fd] px-3 py-1.5 hover:bg-[#1e3a5c] transition-colors">
                <Icon.Bell />
                Notifications
                {actionNotifs.length > 0 && <span className="bg-[#ef4444] text-white text-[10px] font-bold px-1.5 py-0.5 rounded-full">{actionNotifs.length}</span>}
              </button>
              <button onClick={onGoToGrievances} className="flex items-center gap-1.5 text-xs bg-[#0f2540] border border-[#2d5a8e] text-[#93c5fd] px-3 py-1.5 hover:bg-[#1e3a5c] transition-colors">
                Grievances
                <span className="bg-[#f59e0b] text-[#1a2533] text-[10px] font-bold px-1.5 py-0.5 rounded-full">2</span>
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-[1320px] mx-auto px-6 py-5 space-y-5">

        {/* ── Top Metrics ─────────────────────────────────────────────────────── */}
        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3">
          {[
            { label: 'Requirements Identified', value: reqApplicable.length, sub: `${reqApproved} approved · ${reqInProgress} in progress`, color: 'text-[#1a3a5c]', onClick: onGoToJourney },
            { label: 'Active Applications',      value: APPLICATIONS.length,  sub: '3 departments',                                          color: 'text-[#3730a3]', onClick: () => onGoToApplication('') },
            { label: 'Actions Required',         value: ACTIONS.length,       sub: `${ACTIONS.filter(a => a.urgent).length} urgent`,          color: ACTIONS.length > 0 ? 'text-[#b91c1c]' : 'text-[#94a3b8]', onClick: undefined },
            { label: 'Upcoming Inspections',     value: 1,                    sub: 'DISH · 05 Oct 2026',                                     color: 'text-[#c2410c]', onClick: onGoToInspection },
            { label: 'Upcoming Renewals',        value: 1,                    sub: 'MPCB CTO · 31 Dec 2026',                                 color: 'text-[#6366f1]', onClick: onGoToCompliance },
            { label: 'Compliance Due',           value: complianceDue,        sub: `${complianceActionCount} action · ${complianceDueSoon} due soon`, color: complianceDue > 0 ? 'text-[#d97706]' : 'text-[#94a3b8]', onClick: onGoToCompliance },
          ].map(m => (
            <button key={m.label} onClick={m.onClick}
              className="bg-white border border-[#e2e8f0] px-4 py-3 text-left hover:border-[#1a56db] hover:shadow-sm transition-all group disabled:cursor-default"
              disabled={!m.onClick}
            >
              <p className={`text-2xl font-bold ${m.color}`}>{m.value}</p>
              <p className="text-[11px] font-semibold text-[#374151] mt-0.5 leading-tight group-hover:text-[#1a3a5c]">{m.label}</p>
              <p className="text-[10px] text-[#9aa5b4] mt-0.5 leading-tight">{m.sub}</p>
            </button>
          ))}
        </div>

        {/* ── Main two-column layout ───────────────────────────────────────────── */}
        <div className="grid grid-cols-1 lg:grid-cols-[1fr_320px] gap-5">

          {/* ── LEFT MAIN COLUMN ──────────────────────────────────────────────── */}
          <div className="space-y-5 min-w-0">

            {/* ── A. REGULATORY JOURNEY ─────────────────────────────────────── */}
            <div className="bg-white border border-[#e2e8f0]">
              <div className="px-4 py-2.5 bg-[#f8f9fb] border-b border-[#e8edf2] flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Regulatory Journey</p>
                  <span className="text-[10px] font-semibold text-[#6b7a8d] bg-[#f0f4f8] border border-[#d1d9e0] px-1.5 py-0.5">{reqApplicable.length} requirements · {reqApproved} approved</span>
                </div>
                <div className="flex items-center gap-3">
                  <button onClick={onGoToDependency} className="text-xs text-[#1a56db] hover:underline">Dependency graph →</button>
                  <button onClick={onGoToJourney} className="text-xs border border-[#d1d9e0] text-[#475569] px-2.5 py-1 hover:bg-[#f1f5f9] transition-colors">Full Journey</button>
                </div>
              </div>
              <div className="px-4 pt-4 pb-3">

                {/* Stage pipeline */}
                <div className="overflow-x-auto">
                  <div className="flex items-stretch" style={{ minWidth: 'max-content' }}>
                    {stageStates.map((s, idx) => {
                      const cfg = stageCfg[s.state] || stageCfg['Upcoming']
                      const isCurrent = idx === currentStageIdx
                      const stageNodes = nodes.filter(n => n.stage === s.key && n.applicability !== 'not-applicable')
                      const approvedHere = stageNodes.filter(n => n.displayState === 'approved').length
                      return (
                        <div key={s.key} className="flex items-center">
                          <button onClick={onGoToJourney}
                            className={`flex flex-col items-center px-4 py-3 border-t border-b border-l last:border-r ${cfg.border} ${cfg.bg} hover:opacity-90 transition-all ${isCurrent ? 'shadow-[inset_0_-3px_0_#1a56db]' : ''}`}
                            style={{ minWidth: 100 }}
                          >
                            <span className={`text-[10px] font-bold uppercase tracking-wider flex items-center gap-1 ${cfg.text}`}>
                              <span className={`w-1.5 h-1.5 rounded-full ${cfg.dot}`} />
                              Stage {s.num}
                            </span>
                            <span className={`text-[12px] font-semibold mt-1 ${cfg.text}`}>{s.label}</span>
                            <span className={`text-[9px] mt-1 font-medium ${cfg.text} opacity-80`}>{s.state}</span>
                            {stageNodes.length > 0 && (
                              <span className="text-[9px] text-[#9aa5b4] mt-0.5">{approvedHere}/{stageNodes.length}</span>
                            )}
                          </button>
                          {idx < stageStates.length - 1 && (
                            <div className="flex items-center shrink-0 px-0.5">
                              <div className="w-4 h-px bg-[#d1d9e0]" />
                              <span className="text-[#b0bcc9] text-[8px]">›</span>
                            </div>
                          )}
                        </div>
                      )
                    })}
                  </div>
                </div>

                {/* Active-stage requirement cards */}
                {currentStage && (() => {
                  const stageNodes = nodes.filter(n => n.stage === currentStage.key && n.applicability !== 'not-applicable')
                  return stageNodes.length > 0 ? (
                    <div className="mt-3 pt-3 border-t border-[#f0f4f8]">
                      <p className="text-[10px] font-semibold text-[#6b7a8d] uppercase tracking-wider mb-2.5 flex items-center gap-2">
                        Active stage requirements
                        <span className="font-mono normal-case text-[#9aa5b4]">— {currentStage.label}</span>
                      </p>
                      <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                        {stageNodes.slice(0, 4).map(n => {
                          const cfg = journeyStateCfg(n.displayState)
                          return (
                            <button key={n.id} onClick={() => onGoToReqDetail(n.id)}
                              className={`text-left px-2.5 py-2.5 border ${cfg.border} ${cfg.bg} hover:opacity-80 transition-opacity`}
                            >
                              <p className={`text-[10px] font-semibold ${cfg.textCls} truncate`}>{n.department}</p>
                              <p className="text-[11px] font-medium text-[#374151] mt-0.5 leading-tight">{n.service}</p>
                              {n.slaRemaining && <p className="text-[9px] text-[#6b7a8d] mt-0.5">{n.slaRemaining}</p>}
                              <span className={`mt-1 inline-flex items-center gap-1 text-[9px] font-semibold px-1.5 py-0.5 border ${cfg.badgeCls}`}>
                                {cfg.icon} {cfg.label}
                              </span>
                            </button>
                          )
                        })}
                      </div>
                      {stageNodes.length > 4 && (
                        <button onClick={onGoToJourney} className="mt-2 text-xs text-[#1a56db] hover:underline">
                          +{stageNodes.length - 4} more in {currentStage.label} →
                        </button>
                      )}
                    </div>
                  ) : null
                })()}
              </div>
            </div>

            {/* ── B. ACTION REQUIRED ────────────────────────────────────────── */}
            <div className="bg-white border border-[#fde68a] border-l-4 border-l-[#d97706]">
              <div className="px-4 py-2.5 bg-[#fffbeb] border-b border-[#fde68a] flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <span className="w-2 h-2 rounded-full bg-[#d97706]" />
                  <p className="text-xs font-bold text-[#92400e] uppercase tracking-wider">Action Required</p>
                  <span className="text-[10px] font-bold bg-[#d97706] text-white px-2 py-0.5 rounded-full">{ACTIONS.length}</span>
                  <span className="text-[10px] text-[#b45309]">· {ACTIONS.filter(a => a.urgent).length} urgent</span>
                </div>
                <button onClick={onGoToNotifications} className="text-[11px] text-[#92400e] hover:underline">All notifications →</button>
              </div>
              <div className="divide-y divide-[#fef9e7]">
                {ACTIONS.map(a => (
                  <div key={a.id} className={`px-4 py-3 flex items-center justify-between gap-4 ${a.urgent ? 'bg-[#fffbf0]' : 'bg-white'}`}>
                    <div className="flex items-start gap-3 flex-1 min-w-0">
                      <span className={`mt-0.5 shrink-0 ${a.urgent ? 'text-[#d97706]' : 'text-[#6b7a8d]'}`}>{a.icon}</span>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-semibold text-[#1a2533] leading-tight">{a.label}</p>
                        <p className="text-[11px] text-[#6b7a8d] mt-0.5">{a.sub}</p>
                      </div>
                    </div>
                    <button onClick={() => handleActionNav(a.nav)}
                      className={`text-xs shrink-0 border px-3 py-1.5 font-medium transition-colors ${a.urgent ? 'border-[#d97706] text-[#92400e] hover:bg-[#fef3c7]' : 'border-[#1a56db] text-[#1a56db] hover:bg-[#ebf3ff]'}`}
                    >
                      {a.cta}
                    </button>
                  </div>
                ))}
              </div>
            </div>

            {/* ── C. APPLICATIONS ACROSS DEPARTMENTS ───────────────────────── */}
            <div className="bg-white border border-[#e2e8f0]">
              <div className="px-4 py-2.5 bg-[#f8f9fb] border-b border-[#e8edf2] flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Applications Across Departments</p>
                  <span className="text-[10px] font-semibold text-[#6b7a8d] bg-[#f0f4f8] border border-[#d1d9e0] px-1.5 py-0.5">{APPLICATIONS.length} active</span>
                </div>
                <button onClick={() => onGoToApplication('')} className="text-xs border border-[#d1d9e0] text-[#475569] px-2.5 py-1 hover:bg-[#f1f5f9] transition-colors">Application Tracker</button>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-xs">
                  <thead>
                    <tr className="border-b border-[#e8edf2] bg-[#f8f9fb]">
                      {['Department', 'Service / Application', 'Current Desk', 'Status', 'SLA', 'Action'].map(h => (
                        <th key={h} className="text-left px-3.5 py-2 text-[#9aa5b4] font-semibold uppercase tracking-wider text-[10px]">{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[#f1f5f9]">
                    {APPLICATIONS.map(app => (
                      <tr key={app.id} className="hover:bg-[#f8f9fb] transition-colors">
                        <td className="px-3.5 py-3 font-bold text-[#1a3a5c] whitespace-nowrap">{app.dept}</td>
                        <td className="px-3.5 py-3">
                          <p className="font-semibold text-[#1a2533]">{app.service}</p>
                          <p className="font-mono text-[#9aa5b4] text-[10px] mt-0.5">{app.id}</p>
                        </td>
                        <td className="px-3.5 py-3 text-[#6b7a8d] max-w-[180px]"><span className="line-clamp-2">{app.desk}</span></td>
                        <td className="px-3.5 py-3 whitespace-nowrap">
                          <span className={`text-[10px] font-semibold px-1.5 py-0.5 border ${app.statusCls}`}>{app.status}</span>
                        </td>
                        <td className={`px-3.5 py-3 whitespace-nowrap text-xs font-semibold ${app.slaRed ? 'text-[#b91c1c]' : 'text-[#6b7a8d]'}`}>{app.sla}</td>
                        <td className="px-3.5 py-3 whitespace-nowrap">
                          <button onClick={() => handleAppNav(app.nav)}
                            className={`text-xs px-2.5 py-1 border font-medium transition-colors ${app.status === 'Query Raised' ? 'border-[#d97706] text-[#92400e] hover:bg-[#fef3c7]' : 'border-[#d1d9e0] text-[#475569] hover:bg-[#f1f5f9]'}`}
                          >
                            {app.actionLabel}
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>

            {/* ── Bottom two-column: Regulatory Changes + Incentives ─────────── */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">

              {/* F. REGULATORY CHANGES */}
              <div className="bg-white border border-[#e2e8f0]">
                <div className="px-4 py-2.5 bg-[#f8f9fb] border-b border-[#e8edf2] flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Regulatory Changes</p>
                    <span className="text-[10px] font-semibold text-[#6b7a8d] bg-[#f0f4f8] border border-[#d1d9e0] px-1.5 py-0.5">{regChangesAction.length} relevant</span>
                  </div>
                  <button onClick={onGoToRegChanges} className="text-xs text-[#1a56db] hover:underline">Full view →</button>
                </div>
                <div className="divide-y divide-[#f8f9fb]">
                  {REGULATORY_CHANGES.map(r => (
                    <div key={r.id} className={`px-4 py-3 ${r.impactCategory === 'No action' ? 'opacity-60' : ''}`}>
                      <p className="text-[11px] font-semibold text-[#1a2533] leading-tight mb-1.5">{r.title}</p>
                      <div className="flex flex-wrap gap-1 mb-1.5">
                        {regChangeBadge(r.verification)}
                        {regImpactBadge(r.impactCategory)}
                      </div>
                      <p className="text-[10px] text-[#6b7a8d]">Effective {r.effectiveDate} · {r.department}</p>
                      {r.impactCategory !== 'No action' && (
                        <button onClick={onGoToRegChanges} className="mt-1.5 text-[10px] text-[#1a56db] hover:underline font-medium">Review impact →</button>
                      )}
                    </div>
                  ))}
                </div>
              </div>

              {/* G. INCENTIVES SUMMARY */}
              <div className="bg-white border border-[#e2e8f0]">
                <div className="px-4 py-2.5 bg-[#f8f9fb] border-b border-[#e8edf2] flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Incentives</p>
                    <span className="text-[10px] font-semibold text-[#166534] bg-[#f0fdf4] border border-[#86efac] px-1.5 py-0.5">{incentivesEligible} eligible</span>
                  </div>
                  <button onClick={onGoToIncentives} className="text-xs text-[#1a56db] hover:underline">Full view →</button>
                </div>
                {/* Mini stat row */}
                <div className="grid grid-cols-3 divide-x divide-[#f0f4f8] border-b border-[#f0f4f8]">
                  {[
                    { label: 'Identified',   value: INCENTIVE_SCHEMES.length,    cls: 'text-[#1a3a5c]' },
                    { label: 'Eligible',     value: incentivesEligible,           cls: 'text-[#166534]' },
                    { label: 'Verify',       value: incentivesVerify,             cls: 'text-[#92400e]' },
                  ].map(m => (
                    <div key={m.label} className="px-3 py-2 text-center">
                      <p className={`text-base font-bold ${m.cls}`}>{m.value}</p>
                      <p className="text-[10px] text-[#6b7a8d]">{m.label}</p>
                    </div>
                  ))}
                </div>
                <div className="divide-y divide-[#f8f9fb]">
                  {INCENTIVE_SCHEMES.map(s => (
                    <button key={s.id} onClick={() => onGoToIncentiveDetail(s.id)}
                      className="w-full text-left px-4 py-2.5 hover:bg-[#f8fbff] transition-colors group"
                    >
                      <div className="flex items-start justify-between gap-2">
                        <div className="flex-1 min-w-0">
                          <p className="text-[11px] font-semibold text-[#1a2533] leading-tight group-hover:text-[#1a56db] transition-colors">{s.name}</p>
                          <p className="text-[10px] text-[#6b7a8d] mt-0.5">{s.authority}</p>
                        </div>
                        <span className={`text-[9px] font-bold px-1.5 py-0.5 border shrink-0 mt-0.5 ${s.eligState === 'Appears eligible from available data' ? 'bg-[#f0fdf4] text-[#166534] border-[#86efac]' : s.eligState === 'Needs Verification' ? 'bg-[#fef3c7] text-[#92400e] border-[#fde68a]' : 'bg-[#f8f9fb] text-[#6b7a8d] border-[#d1d9e0]'}`}>
                          {s.eligState === 'Appears eligible from available data' ? 'Eligible' : s.eligState === 'Needs Verification' ? 'Verify' : 'N/A'}
                        </span>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            </div>

            {/* H. COMPLIANCE SUMMARY */}
            <div className="bg-white border border-[#e2e8f0]">
              <div className="px-4 py-2.5 bg-[#f8f9fb] border-b border-[#e8edf2] flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Compliance</p>
                  {complianceActionCount > 0 && (
                    <span className="text-[10px] font-bold bg-[#fee2e2] text-[#b91c1c] border border-[#fca5a5] px-1.5 py-0.5">{complianceActionCount} action required</span>
                  )}
                </div>
                <button onClick={onGoToCompliance} className="text-xs border border-[#d1d9e0] text-[#475569] px-2.5 py-1 hover:bg-[#f1f5f9] transition-colors">Compliance Dashboard</button>
              </div>
              {/* Summary row */}
              <div className="grid grid-cols-5 divide-x divide-[#f0f4f8] border-b border-[#f0f4f8]">
                {[
                  { label: 'Action Required', value: COMPLIANCE_OBLIGATIONS.filter(o => o.status === 'Action Required').length, cls: 'text-[#b91c1c]' },
                  { label: 'Due Soon',         value: COMPLIANCE_OBLIGATIONS.filter(o => o.status === 'Due Soon').length,         cls: 'text-[#d97706]' },
                  { label: 'Overdue',          value: COMPLIANCE_OBLIGATIONS.filter(o => o.status === 'Overdue').length,          cls: 'text-[#b91c1c]' },
                  { label: 'Under Verification',value:COMPLIANCE_OBLIGATIONS.filter(o => o.status === 'Under Verification').length,cls: 'text-[#1a56db]' },
                  { label: 'Total',            value: COMPLIANCE_OBLIGATIONS.length,                                              cls: 'text-[#1a3a5c]' },
                ].map(m => (
                  <div key={m.label} className="px-3 py-2.5 text-center">
                    <p className={`text-xl font-bold ${m.cls}`}>{m.value}</p>
                    <p className="text-[10px] text-[#6b7a8d] leading-tight">{m.label}</p>
                  </div>
                ))}
              </div>
              {/* Obligation rows */}
              <div className="overflow-x-auto">
                <table className="w-full text-xs">
                  <thead>
                    <tr className="border-b border-[#f0f4f8] bg-[#f8f9fb]">
                      {['Obligation', 'Department', 'Category', 'Due Date', 'Status', ''].map(h => (
                        <th key={h} className="text-left px-3.5 py-1.5 text-[#9aa5b4] font-semibold uppercase tracking-wider text-[10px]">{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[#f8f9fb]">
                    {COMPLIANCE_OBLIGATIONS.slice(0, 5).map(o => (
                      <tr key={o.id} className="hover:bg-[#f8f9fb] transition-colors">
                        <td className="px-3.5 py-2.5">
                          <p className="font-semibold text-[#1a2533] truncate max-w-[220px]">{o.name}</p>
                          <p className="text-[10px] font-mono text-[#9aa5b4] mt-0.5">{o.id}</p>
                        </td>
                        <td className="px-3.5 py-2.5 text-[#6b7a8d] whitespace-nowrap">{o.dept}</td>
                        <td className="px-3.5 py-2.5 text-[#6b7a8d] whitespace-nowrap">{o.category}</td>
                        <td className={`px-3.5 py-2.5 whitespace-nowrap font-medium ${o.status === 'Action Required' || o.status === 'Overdue' ? 'text-[#b91c1c]' : 'text-[#374151]'}`}>{o.dueDate}</td>
                        <td className="px-3.5 py-2.5 whitespace-nowrap">{complianceStatusBadge(o.status)}</td>
                        <td className="px-3.5 py-2.5 whitespace-nowrap">
                          <button onClick={() => onGoToComplianceDetail(o.id)} className="text-[10px] text-[#1a56db] hover:underline font-medium">Detail →</button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                {COMPLIANCE_OBLIGATIONS.length > 5 && (
                  <div className="px-4 py-2 border-t border-[#f0f4f8]">
                    <button onClick={onGoToCompliance} className="text-xs text-[#1a56db] hover:underline">
                      +{COMPLIANCE_OBLIGATIONS.length - 5} more obligations →
                    </button>
                  </div>
                )}
              </div>
            </div>

          </div>

          {/* ── RIGHT SIDEBAR ──────────────────────────────────────────────────── */}
          <div className="space-y-5 min-w-0">

            {/* D. UPCOMING */}
            <div className="bg-white border border-[#e2e8f0]">
              <div className="px-4 py-2.5 bg-[#f8f9fb] border-b border-[#e8edf2] flex items-center justify-between">
                <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Upcoming</p>
                <button onClick={onGoToCompliance} className="text-xs text-[#1a56db] hover:underline">All →</button>
              </div>
              <div className="divide-y divide-[#f8f9fb]">
                {UPCOMING_ITEMS.map(u => (
                  <button key={u.label} onClick={() => handleUpcomingNav(u.nav)}
                    className={`w-full text-left px-4 py-2.5 flex items-start gap-3 hover:bg-[#f8fbff] transition-colors ${u.urgent ? 'bg-[#fffbf0]' : ''}`}
                  >
                    <span className={`mt-0.5 w-1.5 h-1.5 rounded-full shrink-0 mt-1.5 ${u.dotCls}`} />
                    <div className="flex-1 min-w-0">
                      <p className={`text-[11px] font-semibold leading-tight ${u.urgent ? 'text-[#92400e]' : 'text-[#1a2533]'}`}>{u.label}</p>
                      <div className="flex items-center gap-2 mt-0.5 flex-wrap">
                        <span className={`text-[10px] font-medium ${u.textCls}`}>{u.date}</span>
                        <span className={`text-[9px] font-semibold px-1 py-0.5 border ${u.urgent ? 'bg-[#fee2e2] text-[#b91c1c] border-[#fca5a5]' : 'bg-[#f8f9fb] text-[#6b7a8d] border-[#e2e8f0]'}`}>{u.type}</span>
                      </div>
                    </div>
                    {u.days <= 30 && (
                      <span className={`text-[10px] font-bold shrink-0 ${u.days <= 7 ? 'text-[#b91c1c]' : 'text-[#d97706]'}`}>{u.days}d</span>
                    )}
                  </button>
                ))}
              </div>
            </div>

            {/* I. HIGH-PRIORITY NOTIFICATIONS */}
            <div className="bg-white border border-[#e2e8f0]">
              <div className="px-4 py-2.5 bg-[#f8f9fb] border-b border-[#e8edf2] flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Notifications</p>
                  {actionNotifs.length > 0 && (
                    <span className="text-[10px] font-bold bg-[#b91c1c] text-white px-1.5 py-0.5 rounded-full">{actionNotifs.length}</span>
                  )}
                </div>
                <button onClick={onGoToNotifications} className="text-xs text-[#1a56db] hover:underline">All →</button>
              </div>
              <div className="divide-y divide-[#f8f9fb]">
                {[...actionNotifs, ...upcomingNotifs, ...infoNotifs].slice(0, 5).map(n => {
                  const IconComp = notifTypeIcon[n.type]
                  const isAction = n.group === 'Action Required'
                  return (
                    <div key={n.id} className={`px-4 py-3 ${isAction ? 'bg-[#fffbf0]' : ''}`}>
                      <div className="flex items-start gap-2.5">
                        <span className={`mt-0.5 shrink-0 ${isAction ? 'text-[#d97706]' : n.group === 'Upcoming' ? 'text-[#6366f1]' : 'text-[#6b7a8d]'}`}>
                          <IconComp />
                        </span>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-start justify-between gap-1">
                            <p className="text-[11px] font-semibold text-[#1a2533] leading-tight flex-1">{n.title}</p>
                            {!n.isRead && <span className="w-1.5 h-1.5 rounded-full bg-[#1a56db] shrink-0 mt-1" />}
                          </div>
                          <p className="text-[10px] text-[#6b7a8d] mt-0.5">{n.due}</p>
                          <button onClick={() => handleNotifNav(n)} className="mt-1.5 text-[10px] text-[#1a56db] hover:underline font-medium">
                            {n.ctaLabel} →
                          </button>
                        </div>
                      </div>
                    </div>
                  )
                })}
              </div>
              <div className="px-4 py-2.5 border-t border-[#f0f4f8]">
                <button onClick={onGoToNotifications} className="text-xs text-[#1a56db] hover:underline font-medium">
                  View Notification Centre →
                </button>
              </div>
            </div>

            {/* E. RECENT ACTIVITY */}
            <div className="bg-white border border-[#e2e8f0]">
              <div className="px-4 py-2.5 bg-[#f8f9fb] border-b border-[#e8edf2]">
                <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Recent Activity</p>
              </div>
              <div className="divide-y divide-[#f8f9fb]">
                {ACTIVITY.map((a, i) => (
                  <div key={i} className="px-4 py-2.5 flex items-start gap-2.5">
                    <div className={`mt-1.5 w-1.5 h-1.5 rounded-full shrink-0 ${activityDot[a.type] || 'bg-[#94a3b8]'}`} />
                    <div className="flex-1 min-w-0">
                      <p className="text-[11px] text-[#374151] leading-snug">{a.text}</p>
                      <p className="text-[10px] text-[#9aa5b4] mt-0.5">{a.ts}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>

          </div>
        </div>
      </div>
    </main>
  )
}

