function incentiveStatusBadge(status: IncentiveStatus) {
  const cfg = {
    'strong-match':   { label: 'Strong Match',        cls: 'bg-[#f0fdf4] text-[#166534] border-[#86efac]' },
    'conditional':    { label: 'Conditional Match',   cls: 'bg-[#fef3c7] text-[#92400e] border-[#fde68a]' },
    'needs-info':     { label: 'Needs Information',   cls: 'bg-[#f0f9ff] text-[#1e3a5c] border-[#93c5fd]' },
    'not-applicable': { label: 'Not Applicable',      cls: 'bg-[#f8f9fb] text-[#6b7a8d] border-[#d1d9e0]' },
  }[status]
  return <span className={`text-[10px] font-bold px-2 py-0.5 border ${cfg.cls}`}>{cfg.label}</span>
}

function claimStatusBadge(status: ClaimStatus) {
  const cfg: Record<ClaimStatus, { label: string; cls: string }> = {
    preparing:     { label: 'Preparing',      cls: 'bg-[#f0f4f8] text-[#475569] border-[#d1d9e0]' },
    submitted:     { label: 'Submitted',      cls: 'bg-[#ede9fe] text-[#3730a3] border-[#a5b4fc]' },
    'under-review':{ label: 'Under Review',   cls: 'bg-[#ede9fe] text-[#3730a3] border-[#a5b4fc]' },
    'query-raised':{ label: 'Query Raised',   cls: 'bg-[#fef3c7] text-[#92400e] border-[#fde68a]' },
    resubmitted:   { label: 'Resubmitted',    cls: 'bg-[#f0fdf4] text-[#166534] border-[#86efac]' },
    approved:      { label: 'Approved',       cls: 'bg-[#f0fdf4] text-[#166534] border-[#86efac]' },
    received:      { label: 'Benefit Received', cls: 'bg-[#f0fdf4] text-[#166534] border-[#86efac]' },
  }
  const c = cfg[status]
  return <span className={`text-[10px] font-bold px-2 py-0.5 border ${c.cls}`}>{c.label}</span>
}

function SourceBadge({ source }: { source: string }) {
  const verified = source.includes('Verified') || source.includes('Benchmark')
  const selfDecl = source.includes('Self-declared') || source.includes('Assumption')
  const cls = verified
    ? 'bg-[#f0fdf4] text-[#166534] border-[#86efac]'
    : selfDecl
      ? 'bg-[#fef3c7] text-[#92400e] border-[#fde68a]'
      : 'bg-[#f0f4f8] text-[#475569] border-[#d1d9e0]'
  return <span className={`text-[9px] font-semibold px-1.5 py-0.5 border ${cls}`}>{source}</span>
}

// ── Shared Incentive page header ──────────────────────────────────────────────
function IncentivePageHeader({
  title, subtitle, breadcrumb,
  onGoToOverview, onOpenRegAssistant,
}: {
  title: string; subtitle?: string
  breadcrumb: string[]
  onGoToOverview: () => void
  onOpenRegAssistant?: () => void
}) {
  return (
    <div className="bg-white border-b border-[#d1d9e0] px-6 py-4">
      <div className="max-w-[1320px] mx-auto">
        <nav className="text-xs text-[#6b7a8d] mb-2 flex items-center gap-1.5 flex-wrap">
          {breadcrumb.map((crumb, i) => (
            <React.Fragment key={crumb}>
              {i > 0 && <span className="text-[#d1d9e0]">›</span>}
              {i < breadcrumb.length - 1
                ? <button onClick={onGoToOverview} className="hover:text-[#1a56db] hover:underline">{crumb}</button>
                : <span className="text-[#1a3a5c] font-medium">{crumb}</span>
              }
            </React.Fragment>
          ))}
        </nav>
        <div className="flex items-start justify-between gap-4 flex-wrap">
          <div>
            <h1 className="text-xl font-bold text-[#1a3a5c]">{title}</h1>
            {subtitle && <p className="text-xs text-[#6b7a8d] mt-0.5 max-w-2xl">{subtitle}</p>}
          </div>
          <div className="flex items-center gap-2 shrink-0">
            {onOpenRegAssistant && (
              <button onClick={onOpenRegAssistant}
                className="flex items-center gap-1.5 text-xs border border-[#6366f1] text-[#4338ca] px-3 py-1.5 hover:bg-[#eef2ff] transition-colors font-medium"
              >
                <svg width="14" height="14" viewBox="0 0 14 14" fill="none"><circle cx="7" cy="7" r="5.5" stroke="currentColor" strokeWidth="1.3"/><path d="M7 4.5A1 1 0 019 5.5c0 .8-1 1.2-1 2M7 10v.3" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round"/></svg>
                Ask Regulatory Assistant
              </button>
            )}
          </div>
        </div>
        {/* Business context strip */}
        <div className="mt-3 flex items-center gap-3 flex-wrap">
          <div className="flex items-center gap-2 text-[11px] text-[#6b7a8d]">
            <span className="font-semibold text-[#1a3a5c]">ABC Manufacturing Pvt. Ltd.</span>
            <span className="text-[#d1d9e0]">·</span>
            <span>Manufacturing</span>
            <span className="text-[#d1d9e0]">·</span>
            <span>Ratnagiri, Maharashtra</span>
            <span className="text-[#d1d9e0]">·</span>
            <span>New Unit</span>
            <span className="text-[#d1d9e0]">·</span>
            <span className="font-medium text-[#6366f1]">MSME</span>
            <span className="text-[#d1d9e0]">·</span>
            <span className="text-[10px] bg-[#f0f4f8] border border-[#d1d9e0] px-1.5 py-0.5 text-[#6b7a8d]">Business DNA v4</span>
          </div>
        </div>
      </div>
    </div>
  )
}

// ── I01 — Incentive Centre ─────────────────────────────────────────────────────
function I01IncentiveCentrePage({
  onGoToCalculator, onGoToROI, onGoToScenarios, onGoToReadiness, onGoToPortfolio,
  onGoToDetail, onGoToTracker, onGoPolicyUpdates, onOpenRegAssistant,
}: {
  onGoToCalculator: () => void; onGoToROI: () => void; onGoToScenarios: () => void
  onGoToReadiness: () => void; onGoToPortfolio: () => void
  onGoToDetail: (id: string) => void; onGoToTracker: (id: string) => void
  onGoPolicyUpdates: () => void; onOpenRegAssistant?: () => void
}) {
  const [activeTab, setActiveTab] = useState<'all' | 'strong' | 'conditional' | 'needs-info' | 'claims' | 'received'>('all')

  const strong     = INCENTIVE_DETAIL_SCHEMES.filter(s => s.status === 'strong-match')
  const conditional= INCENTIVE_DETAIL_SCHEMES.filter(s => s.status === 'conditional')
  const needsInfo  = INCENTIVE_DETAIL_SCHEMES.filter(s => s.status === 'needs-info')

  const visible = activeTab === 'all'        ? INCENTIVE_DETAIL_SCHEMES
    : activeTab === 'strong'                 ? strong
    : activeTab === 'conditional'            ? conditional
    : activeTab === 'needs-info'             ? needsInfo
    : activeTab === 'claims'                 ? INCENTIVE_DETAIL_SCHEMES.filter(s => s.claimId)
    : []

  const tabs = [
    { id: 'all',         label: 'All Opportunities',   count: INCENTIVE_DETAIL_SCHEMES.length },
    { id: 'strong',      label: 'Strong Matches',      count: strong.length },
    { id: 'conditional', label: 'Conditional',         count: conditional.length },
    { id: 'needs-info',  label: 'Needs Information',   count: needsInfo.length },
    { id: 'claims',      label: 'Claims in Progress',  count: INCENTIVE_CLAIMS.length },
    { id: 'received',    label: 'Received / Completed',count: 0 },
  ] as const

  return (
    <main id="main-content" className="flex-1 bg-[#f8f9fb]" tabIndex={-1}>
      <IncentivePageHeader
        title="Incentives"
        subtitle="Discover applicable government incentives, estimate their potential financial impact, compare investment scenarios and prepare claims."
        breadcrumb={['Home', 'ABC Manufacturing Pvt. Ltd.', 'Incentives']}
        onGoToOverview={() => {}}
        onOpenRegAssistant={onOpenRegAssistant}
      />

      <div className="max-w-[1320px] mx-auto px-6 py-5 space-y-5">

        {/* Hero — Incentive Opportunity */}
        <div className="bg-[#1a3a5c] text-white px-6 py-5">
          <div className="flex items-start justify-between gap-6 flex-wrap">
            <div className="flex-1 min-w-0">
              <p className="text-[10px] font-bold uppercase tracking-widest text-[#93c5fd] mb-2">Your Incentive Opportunity</p>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mb-4">
                {[
                  { label: 'Potential Incentives', value: '7', sub: 'identified' },
                  { label: 'Strong Matches', value: '4', sub: 'criteria satisfied', accent: '#86efac' },
                  { label: 'Needs Information', value: '2', sub: 'pending inputs', accent: '#fde68a' },
                  { label: 'Claims in Progress', value: '1', sub: 'being prepared', accent: '#a5b4fc' },
                ].map(m => (
                  <div key={m.label}>
                    <p className="text-2xl font-bold" style={m.accent ? { color: m.accent } : {}}>{m.value}</p>
                    <p className="text-[11px] font-semibold text-[#cbd5e1] leading-tight">{m.label}</p>
                    <p className="text-[10px] text-[#94a3b8] mt-0.5">{m.sub}</p>
                  </div>
                ))}
              </div>
              <div className="border-t border-[#2d5a8e] pt-3">
                <p className="text-[10px] text-[#94a3b8] mb-1 uppercase tracking-wider font-semibold">Estimated Potential Support</p>
                <p className="text-2xl font-bold text-white">₹1.33 Cr – ₹2.31 Cr</p>
                <p className="text-[10px] text-[#64748b] mt-1 max-w-xl leading-relaxed">Indicative estimate based on current Business DNA and available project information. Final eligibility and admissible amount are subject to applicable policy conditions and departmental verification.</p>
              </div>
            </div>
            <div className="flex flex-col gap-2 shrink-0">
              <button onClick={onGoToCalculator} className="bg-white text-[#1a3a5c] text-sm font-bold px-5 py-2.5 hover:bg-[#f0f4f8] transition-colors whitespace-nowrap">
                Calculate / Refresh Incentives
              </button>
              <button onClick={onGoToScenarios} className="border border-[#2d5a8e] text-white text-sm font-medium px-5 py-2 hover:bg-[#0f2540] transition-colors whitespace-nowrap">
                Compare Investment Scenarios
              </button>
              <button onClick={onGoToReadiness} className="border border-[#2d5a8e] text-[#93c5fd] text-sm font-medium px-5 py-2 hover:bg-[#0f2540] transition-colors whitespace-nowrap">
                Check Claim Readiness
              </button>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-[1fr_280px] gap-5">
          <div className="space-y-4 min-w-0">

            {/* Tabs */}
            <div className="bg-white border border-[#e2e8f0]">
              <div className="flex overflow-x-auto border-b border-[#e2e8f0]">
                {tabs.map(t => (
                  <button key={t.id}
                    onClick={() => setActiveTab(t.id)}
                    className={`px-4 py-2.5 text-xs font-semibold whitespace-nowrap flex items-center gap-1.5 border-b-2 transition-colors ${activeTab === t.id ? 'border-[#1a56db] text-[#1a3a5c] bg-[#f8fbff]' : 'border-transparent text-[#6b7a8d] hover:text-[#1a3a5c]'}`}
                  >
                    {t.label}
                    <span className={`text-[10px] px-1.5 py-0.5 rounded-full font-bold ${activeTab === t.id ? 'bg-[#1a56db] text-white' : 'bg-[#e2e8f0] text-[#6b7a8d]'}`}>{t.count}</span>
                  </button>
                ))}
              </div>

              {/* Opportunity cards */}
              <div className="divide-y divide-[#f8f9fb]">
                {visible.length === 0 ? (
                  <div className="px-5 py-8 text-center text-sm text-[#6b7a8d]">No opportunities in this category yet.</div>
                ) : visible.map(scheme => (
                  <div key={scheme.id} className="px-5 py-4">
                    <div className="flex items-start justify-between gap-4 flex-wrap">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-start gap-2 flex-wrap mb-1.5">
                          <p className="text-sm font-bold text-[#1a2533] leading-tight">{scheme.name}</p>
                          {incentiveStatusBadge(scheme.status)}
                        </div>
                        <p className="text-[11px] text-[#6b7a8d] mb-2">{scheme.authority}</p>
                        {scheme.status !== 'needs-info' && (
                          <p className="text-[11px] font-semibold text-[#1a3a5c] mb-2">
                            Estimated Benefit: ₹{scheme.estimatedMin}–₹{scheme.estimatedMax} {scheme.unit === 'lakh' ? 'Lakh' : 'Cr'} · {scheme.period}
                          </p>
                        )}
                        {/* Criteria quick view */}
                        <div className="flex flex-wrap gap-x-4 gap-y-0.5">
                          {scheme.criteria.slice(0, 4).map(c => (
                            <span key={c.label} className={`text-[10px] flex items-center gap-1 ${c.met ? 'text-[#166534]' : 'text-[#92400e]'}`}>
                              <span>{c.met ? '✓' : '⚠'}</span> {c.label}
                            </span>
                          ))}
                        </div>
                        {scheme.missingInfo && scheme.missingInfo.length > 0 && (
                          <div className="mt-2">
                            <p className="text-[10px] font-semibold text-[#6b7a8d] uppercase tracking-wider mb-1">Additional information required:</p>
                            {scheme.missingInfo.map(m => (
                              <p key={m} className="text-[10px] text-[#374151]">· {m}</p>
                            ))}
                          </div>
                        )}
                      </div>
                      <div className="flex flex-col gap-2 shrink-0">
                        {scheme.status === 'needs-info'
                          ? <button onClick={onGoToCalculator} className="text-xs border border-[#1a56db] text-[#1a56db] px-3 py-1.5 hover:bg-[#ebf3ff] transition-colors font-medium">Provide Information</button>
                          : scheme.status === 'conditional'
                            ? <button onClick={() => onGoToDetail(scheme.id)} className="text-xs border border-[#d97706] text-[#92400e] px-3 py-1.5 hover:bg-[#fef3c7] transition-colors font-medium">Complete Information</button>
                            : <button onClick={() => onGoToDetail(scheme.id)} className="text-xs bg-[#1a3a5c] text-white px-3 py-1.5 hover:bg-[#0f2540] transition-colors font-medium">View Details</button>
                        }
                        {scheme.status === 'strong-match' && (
                          <button onClick={onGoToReadiness} className="text-xs border border-[#d1d9e0] text-[#475569] px-3 py-1.5 hover:bg-[#f1f5f9] transition-colors">Claim Readiness</button>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Claims section */}
            <div className="bg-white border border-[#e2e8f0]">
              <div className="px-5 py-2.5 bg-[#f8f9fb] border-b border-[#e8edf2] flex items-center justify-between">
                <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Claims</p>
                <button onClick={() => onGoToTracker('')} className="text-xs text-[#1a56db] hover:underline">All claims →</button>
              </div>
              {INCENTIVE_CLAIMS.length === 0 ? (
                <div className="px-5 py-6 text-center text-sm text-[#6b7a8d]">No claims in progress. When you are ready to claim an eligible incentive, start here.</div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full text-xs">
                    <thead>
                      <tr className="border-b border-[#f0f4f8] bg-[#f8f9fb]">
                        {['Scheme', 'Claim ID', 'Estimated Amount', 'Status', 'Last Updated', 'Next Action', ''].map(h => (
                          <th key={h} className="text-left px-4 py-2 text-[10px] font-semibold text-[#9aa5b4] uppercase tracking-wider">{h}</th>
                        ))}
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-[#f8f9fb]">
                      {INCENTIVE_CLAIMS.map(c => (
                        <tr key={c.id} className="hover:bg-[#f8fbff] transition-colors">
                          <td className="px-4 py-3 font-semibold text-[#1a2533] max-w-[200px]"><span className="line-clamp-2">{c.schemeName}</span></td>
                          <td className="px-4 py-3 font-mono text-[#6b7a8d]">{c.id}</td>
                          <td className="px-4 py-3 font-semibold text-[#1a3a5c]">{c.amount}</td>
                          <td className="px-4 py-3">{claimStatusBadge(c.status)}</td>
                          <td className="px-4 py-3 text-[#6b7a8d]">{c.updated}</td>
                          <td className="px-4 py-3 text-[#d97706] font-medium">{c.nextAction}</td>
                          <td className="px-4 py-3">
                            <button onClick={() => onGoToTracker(c.id)} className="text-[10px] text-[#1a56db] hover:underline font-medium">View →</button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>

            {/* Policy Updates */}
            <div className="bg-white border border-[#e2e8f0]">
              <div className="px-5 py-2.5 bg-[#f8f9fb] border-b border-[#e8edf2] flex items-center justify-between">
                <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider flex items-center gap-2">
                  Incentive Policy Updates
                  <span className="text-[10px] bg-[#fee2e2] text-[#b91c1c] border border-[#fca5a5] px-1.5 py-0.5 font-bold">{INCENTIVE_POLICY_UPDATES.length} new</span>
                </p>
                <button onClick={onGoPolicyUpdates} className="text-xs text-[#1a56db] hover:underline">All updates →</button>
              </div>
              <div className="divide-y divide-[#f8f9fb]">
                {INCENTIVE_POLICY_UPDATES.map(u => (
                  <div key={u.id} className="px-5 py-3">
                    <div className="flex items-start justify-between gap-3">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1 flex-wrap">
                          <span className={`text-[9px] font-bold px-1.5 py-0.5 border uppercase tracking-wider ${u.type === 'new-scheme' ? 'bg-[#f0fdf4] text-[#166534] border-[#86efac]' : 'bg-[#ede9fe] text-[#3730a3] border-[#a5b4fc]'}`}>
                            {u.type === 'new-scheme' ? 'New Opportunity' : 'Amendment'}
                          </span>
                          {u.validated ? <span className="text-[9px] font-semibold text-[#166534]">✓ Validated</span> : <span className="text-[9px] font-semibold text-[#d97706]">⚠ Draft / Under Validation</span>}
                        </div>
                        <p className="text-[11px] font-semibold text-[#1a2533] leading-tight">{u.title}</p>
                        <p className="text-[10px] text-[#6b7a8d] mt-0.5">{u.summary}</p>
                        <p className="text-[10px] text-[#6b7a8d] mt-1">Effective: {u.effectiveDate} · Detected: {u.detected}</p>
                      </div>
                      <button onClick={onGoPolicyUpdates} className="text-xs border border-[#d1d9e0] text-[#475569] px-2.5 py-1 hover:bg-[#f1f5f9] transition-colors shrink-0">View Impact</button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Quick Actions sidebar */}
          <div className="space-y-4">
            <div className="bg-white border border-[#e2e8f0]">
              <div className="px-4 py-2.5 bg-[#f8f9fb] border-b border-[#e8edf2]">
                <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">Quick Actions</p>
              </div>
              <div className="divide-y divide-[#f8f9fb]">
                {[
                  { label: 'Calculate Incentives', sub: 'Refresh with latest inputs', onClick: onGoToCalculator, icon: '⟳' },
                  { label: 'ROI & Scenario Planner', sub: 'Model financial impact', onClick: onGoToROI, icon: '↗' },
                  { label: 'Compare Scenarios', sub: 'Side-by-side comparison', onClick: onGoToScenarios, icon: '⇌' },
                  { label: 'Claim Readiness', sub: 'Check evidence coverage', onClick: onGoToReadiness, icon: '✓' },
                  { label: 'Policy Updates', sub: '2 updates requiring review', onClick: onGoPolicyUpdates, icon: '!' },
                  { label: 'Ask Regulatory Assistant', sub: 'Ask about your incentives', onClick: onOpenRegAssistant ?? (() => {}), icon: '?' },
                ].map(a => (
                  <button key={a.label} onClick={a.onClick} className="w-full text-left px-4 py-3 hover:bg-[#f8fbff] transition-colors group">
                    <div className="flex items-center gap-3">
                      <span className="w-7 h-7 bg-[#f0f4f8] border border-[#e2e8f0] flex items-center justify-center text-[#1a3a5c] font-bold text-xs shrink-0 group-hover:bg-[#ebf3ff] group-hover:border-[#93c5fd]">{a.icon}</span>
                      <div>
                        <p className="text-[11px] font-semibold text-[#1a2533] group-hover:text-[#1a56db]">{a.label}</p>
                        <p className="text-[10px] text-[#6b7a8d]">{a.sub}</p>
                      </div>
                    </div>
                  </button>
                ))}
              </div>
            </div>

            {/* Sensitivity / Missing */}
            <div className="bg-white border border-[#fde68a] border-l-4 border-l-[#d97706]">
              <div className="px-4 py-2.5 bg-[#fffbeb] border-b border-[#fde68a]">
                <p className="text-xs font-bold text-[#92400e] uppercase tracking-wider">Limiting Assessment</p>
              </div>
              <div className="px-4 py-3">
                <p className="text-xs text-[#374151] mb-2">3 additional opportunities cannot yet be fully assessed due to missing inputs:</p>
                {['Employment projection (headcount)', 'Plant & machinery cost breakup', 'Commercial production date'].map((m, i) => (
                  <div key={m} className="flex items-start gap-2 mb-1.5">
                    <span className="text-[10px] font-bold text-[#d97706] shrink-0 mt-0.5">{i + 1}.</span>
                    <p className="text-[11px] text-[#374151]">{m}</p>
                  </div>
                ))}
                <button onClick={onGoToCalculator} className="mt-2 text-xs border border-[#d97706] text-[#92400e] px-3 py-1.5 hover:bg-[#fef3c7] transition-colors font-medium w-full">
                  Complete Missing Information
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </main>
  )
}

// ── I02 — Calculator Start / Business DNA Reuse ────────────────────────────────
function I02CalculatorPage({
  onBack, onNext, onOpenRegAssistant,
}: {
  onBack: () => void; onNext: () => void; onOpenRegAssistant?: () => void
}) {
  const [step] = useState(1)
  const steps = ['Business', 'Location', 'Investment', 'Operations', 'Review']

  const dnaFields = [
    { label: 'Business Activity', value: 'Manufacturing — Pharmaceutical', status: 'Department Verified', ok: true },
    { label: 'Project Location', value: 'Ratnagiri, Maharashtra', status: 'Business DNA — Verified', ok: true },
    { label: 'Project Type', value: 'New Unit', status: 'User Confirmed', ok: true },
    { label: 'Enterprise Category', value: 'MSME — Small Enterprise', status: 'Business DNA — Verified', ok: true },
    { label: 'Total Fixed Capital Investment', value: '₹10.0 Cr', status: 'User Confirmed', ok: true },
    { label: 'Plant & Machinery', value: '₹8.0 Cr', status: 'User Confirmed', ok: true },
    { label: 'Building & Civil Works', value: '₹1.5 Cr', status: 'User Confirmed', ok: true },
    { label: 'MIDC Plot — Location', value: 'Ratnagiri MIDC Phase I', status: 'Business DNA — Verified', ok: true },
    { label: 'MIDC Allotment Status', value: 'Allotted — Active', status: 'System Verified', ok: true },
    { label: 'Expected Employment', value: '150 persons', status: 'Self-declared', ok: true },
    { label: 'Expected Annual Turnover (Yr 3)', value: '₹18 Cr', status: 'Self-declared', ok: true },
    { label: 'Production Capacity', value: '5,000 MT/year', status: 'Business DNA', ok: true },
    { label: 'GSTIN Registration', value: '27AABCM1234Q1Z5', status: 'System Verified', ok: true },
  ]

  const missing = [
    { label: 'Electricity Consumption (kWh/year)', hint: 'Required for Electricity Duty Exemption assessment' },
    { label: 'Connected Load (kVA)', hint: 'Required for Electricity Duty calculation' },
    { label: 'Green / Energy Efficiency Investment (₹)', hint: 'Required to evaluate sustainability incentives' },
    { label: 'Commercial Production Date (expected)', hint: 'Required for timeline-linked incentive eligibility' },
    { label: 'R&D Expenditure Budget (₹ Lakh)', hint: 'Required for Innovation / R&D support assessment' },
  ]

  return (
    <main id="main-content" className="flex-1 bg-[#f8f9fb]" tabIndex={-1}>
      <IncentivePageHeader
        title="Calculate Incentives"
        subtitle="We reuse verified Business DNA to minimise manual input."
        breadcrumb={['Home', 'ABC Manufacturing Pvt. Ltd.', 'Incentives', 'Calculate Incentives']}
        onGoToOverview={onBack}
        onOpenRegAssistant={onOpenRegAssistant}
      />

      <div className="max-w-[900px] mx-auto px-6 py-5 space-y-5">
        {/* Step indicator */}
        <div className="flex items-center gap-0 overflow-x-auto">
          {steps.map((s, i) => (
            <React.Fragment key={s}>
              <div className={`flex items-center gap-1.5 px-3 py-2 text-xs font-semibold shrink-0 ${i === step - 1 ? 'bg-[#1a3a5c] text-white' : i < step - 1 ? 'bg-[#f0fdf4] text-[#166534] border border-[#86efac]' : 'bg-white border border-[#e2e8f0] text-[#9aa5b4]'}`}>
                <span className={`w-4 h-4 rounded-full flex items-center justify-center text-[10px] font-bold shrink-0 ${i === step - 1 ? 'bg-white text-[#1a3a5c]' : i < step - 1 ? 'bg-[#22c55e] text-white' : 'bg-[#e2e8f0] text-[#9aa5b4]'}`}>
                  {i < step - 1 ? '✓' : i + 1}
                </span>
                {s}
              </div>
              {i < steps.length - 1 && <div className="w-5 h-px bg-[#d1d9e0] shrink-0" />}
            </React.Fragment>
          ))}
        </div>

        {/* DNA Reuse panel */}
        <div className="bg-white border border-[#e2e8f0]">
          <div className="px-5 py-3 bg-[#f0fdf4] border-b border-[#86efac] flex items-center justify-between">
            <div className="flex items-center gap-2">
              <span className="text-[#16a34a] font-bold">✓</span>
              <p className="text-xs font-bold text-[#166534]">Most information has already been reused from your verified Business DNA</p>
            </div>
            <span className="text-[11px] font-semibold text-[#166534] bg-[#dcfce7] border border-[#86efac] px-2 py-0.5">{dnaFields.length} of {dnaFields.length + missing.length} parameters available</span>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b border-[#f0f4f8] bg-[#f8f9fb]">
                  {['Parameter', 'Value', 'Source / Verification'].map(h => (
                    <th key={h} className="text-left px-4 py-2 text-[10px] font-semibold text-[#9aa5b4] uppercase tracking-wider">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-[#f8f9fb]">
                {dnaFields.map(f => (
                  <tr key={f.label} className="hover:bg-[#f8f9fb]">
                    <td className="px-4 py-2.5 font-medium text-[#374151]">{f.label}</td>
                    <td className="px-4 py-2.5 text-[#1a2533] font-semibold">{f.value}</td>
                    <td className="px-4 py-2.5"><SourceBadge source={f.status} /></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Missing info */}
        <div className="bg-white border border-[#fde68a] border-l-4 border-l-[#d97706]">
          <div className="px-5 py-3 bg-[#fffbeb] border-b border-[#fde68a] flex items-center justify-between">
            <p className="text-xs font-bold text-[#92400e]">{missing.length} additional inputs required to evaluate all potential incentives</p>
            <span className="text-[11px] font-semibold text-[#92400e] bg-[#fef3c7] border border-[#fde68a] px-2 py-0.5">{missing.length} of {dnaFields.length + missing.length} remaining</span>
          </div>
          <div className="divide-y divide-[#fef9e7]">
            {missing.map(m => (
              <div key={m.label} className="px-5 py-3 flex items-center justify-between gap-3">
                <div>
                  <p className="text-[11px] font-semibold text-[#1a2533]">{m.label}</p>
                  <p className="text-[10px] text-[#6b7a8d] mt-0.5">{m.hint}</p>
                </div>
                <span className="text-[10px] text-[#d97706] font-bold shrink-0">Required</span>
              </div>
            ))}
          </div>
        </div>

        <div className="flex items-center justify-between pt-2">
          <button onClick={onBack} className="text-xs border border-[#d1d9e0] text-[#475569] px-4 py-2 hover:bg-[#f1f5f9] transition-colors">Back</button>
          <button onClick={onNext} className="bg-[#1a3a5c] text-white text-sm font-semibold px-6 py-2.5 hover:bg-[#0f2540] transition-colors">
            Continue — Provide Missing Information →
          </button>
        </div>
      </div>
    </main>
  )
}

// ── I03 — Adaptive Questionnaire ──────────────────────────────────────────────
function I03QuestionnairePage({
  onBack, onNext, onOpenRegAssistant,
}: {
  onBack: () => void; onNext: () => void; onOpenRegAssistant?: () => void
}) {
  const [answers, setAnswers] = useState<Record<string, string>>({})
  const [openHint, setOpenHint] = useState<string | null>(null)

  const questions = [
    { id: 'elec-kwh', label: 'Expected Annual Electricity Consumption', unit: 'kWh/year', hint: 'Certain incentive schemes depend on electricity usage. This is used only to estimate the Electricity Duty Exemption benefit under PSI 2019.', group: 'Core' },
    { id: 'elec-kva', label: 'Sanctioned Connected Load', unit: 'kVA', hint: 'Required to verify eligibility for industrial electricity tariff-linked exemptions.', group: 'Core' },
    { id: 'prod-date', label: 'Expected Commercial Production Date', unit: 'MM/YYYY', hint: 'Timeline-linked incentives (such as capital subsidy) require a commercial production date to determine eligibility window.', group: 'Core' },
    { id: 'green-ee', label: 'Proposed Energy Efficiency Investment', unit: '₹ Lakh', hint: 'Required to assess eligibility for the Green Industry Incentive Scheme. Only relevant if you are investing in energy-efficient equipment.', group: 'Sustainability' },
    { id: 'green-re', label: 'Proposed Renewable Energy Investment', unit: '₹ Lakh', hint: 'Investments in solar, wind or biomass energy may unlock additional green incentives.', group: 'Sustainability' },
    { id: 'rd-exp', label: 'Planned R&D Expenditure', unit: '₹ Lakh', hint: 'R&D investment may qualify for MSME Innovation support or DST grant schemes. Leave blank if not applicable.', group: 'R&D / Innovation' },
  ]

  const groups = [...new Set(questions.map(q => q.group))]

  return (
    <main id="main-content" className="flex-1 bg-[#f8f9fb]" tabIndex={-1}>
      <IncentivePageHeader
        title="Provide Missing Information"
        subtitle="These are the only additional inputs needed. All other parameters have been sourced from your Business DNA."
        breadcrumb={['Home', 'ABC Manufacturing Pvt. Ltd.', 'Incentives', 'Calculate Incentives', 'Questionnaire']}
        onGoToOverview={onBack}
        onOpenRegAssistant={onOpenRegAssistant}
      />

      <div className="max-w-[720px] mx-auto px-6 py-5 space-y-5">
        <div className="bg-[#f0fdf4] border border-[#86efac] px-4 py-3 text-xs text-[#166534] font-medium">
          ✓ 13 of 18 required parameters already available from Business DNA. Only 5 additional inputs are shown below.
        </div>

        {groups.map(group => (
          <div key={group} className="bg-white border border-[#e2e8f0]">
            <div className="px-5 py-2.5 bg-[#f8f9fb] border-b border-[#e8edf2]">
              <p className="text-xs font-bold text-[#1a3a5c] uppercase tracking-wider">{group} Information</p>
            </div>
            <div className="divide-y divide-[#f8f9fb]">
              {questions.filter(q => q.group === group).map(q => (
                <div key={q.id} className="px-5 py-4">
                  <div className="flex items-start justify-between gap-4 mb-2">
                    <label className="text-sm font-semibold text-[#1a2533]">{q.label}</label>
                    <button
                      onClick={() => setOpenHint(openHint === q.id ? null : q.id)}
                      className="text-[#6366f1] text-[11px] font-medium hover:underline shrink-0 flex items-center gap-1"
                    >
                      <svg width="12" height="12" viewBox="0 0 12 12" fill="none"><circle cx="6" cy="6" r="5" stroke="currentColor" strokeWidth="1.2"/><path d="M6 4A.75.75 0 017.5 4.75c0 .6-.75.9-.75 1.75M6 8.5v.3" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round"/></svg>
                      Why do we need this?
                    </button>
                  </div>
                  {openHint === q.id && (
                    <div className="mb-3 bg-[#f0f9ff] border border-[#93c5fd] px-3 py-2.5 text-[11px] text-[#1e3a5c] leading-relaxed">
                      <p className="font-semibold text-[#1a56db] mb-1 flex items-center gap-1">
                        <svg width="12" height="12" viewBox="0 0 12 12" fill="none"><circle cx="6" cy="6" r="5" stroke="currentColor" strokeWidth="1.2"/><path d="M6 4A.75.75 0 017.5 4.75c0 .6-.75.9-.75 1.75M6 8.5v.3" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round"/></svg>
                        Why is this required?
                      </p>
                      {q.hint}
                    </div>
                  )}
                  <div className="flex items-center gap-2">
                    <input
                      type="text"
                      placeholder={`Enter ${q.unit}`}
                      value={answers[q.id] || ''}
                      onChange={e => setAnswers({ ...answers, [q.id]: e.target.value })}
                      className="flex-1 border border-[#d1d9e0] text-sm px-3 py-2 focus:outline-none focus:border-[#1a56db] focus:ring-1 focus:ring-[#1a56db] text-[#1a2533] placeholder:text-[#9aa5b4]"
                    />
                    <span className="text-xs text-[#6b7a8d] shrink-0">{q.unit}</span>
                  </div>
                  <p className="text-[10px] text-[#9aa5b4] mt-1">Optional — skip if not applicable to your project</p>
                </div>
              ))}
            </div>
          </div>
        ))}

        <div className="flex items-center justify-between pt-2">
          <button onClick={onBack} className="text-xs border border-[#d1d9e0] text-[#475569] px-4 py-2 hover:bg-[#f1f5f9] transition-colors">Back</button>
          <button onClick={onNext} className="bg-[#1a3a5c] text-white text-sm font-semibold px-6 py-2.5 hover:bg-[#0f2540] transition-colors">
            Review Before Calculation →
          </button>
        </div>
      </div>
    </main>
  )
}

